function normalizeShipRecord(record,key,legacy){const upgrades={...DEFAULT.upgrades,...(record?.upgrades||(legacy?.upgrades||{}))},capacity=SHIPS[key].fuel+upgrades.tank*SHIPS[key].tankStep,condition=Number.isFinite(record?.condition)?record.condition:Number.isFinite(legacy?.condition)?legacy.condition:100,fuel=Number.isFinite(record?.fuel)?record.fuel:Number.isFinite(legacy?.fuel)?legacy.fuel:SHIPS[key].fuel;return{condition:Math.max(0,Math.min(100,condition)),fuel:Math.max(0,Math.min(fuel,capacity)),upgrades}}
function load(){try{const x=JSON.parse(localStorage.getItem("cosmicCargoSave")||"{}"),active=SHIPS[x.activeShip]?x.activeShip:'courier',legacyTraded=Array.isArray(x.retiredShips)?x.retiredShips:[],owned=[...new Set([...(Array.isArray(x.ownedShips)?x.ownedShips:[]),active])].filter(k=>SHIPS[k]),tradedShips=[...new Set([...(Array.isArray(x.tradedShips)?x.tradedShips:[]),...legacyTraded])].filter(k=>SHIPS[k]&&!owned.includes(k)),shipData={};owned.forEach(k=>shipData[k]=normalizeShipRecord(x.shipData?.[k],k,k===active?x:null));const activeData=shipData[active]||normalizeShipRecord(null,active,x),slotCount=SHIPS[active].slots,compatible=x.cargoLayoutVersion===2&&Array.isArray(x.slots)&&x.slots.length===slotCount;return{...structuredClone(DEFAULT),...x,ownedShips:owned.length?owned:['courier'],retiredShips:[],tradedShips,shipData,activeShip:active,condition:activeData.condition,fuel:activeData.fuel,upgrades:activeData.upgrades,slots:compatible?x.slots:Array(slotCount).fill(null),cargoRotations:compatible&&x.cargoRotations?x.cargoRotations:{},cargoLayoutVersion:2}}catch{const fresh=structuredClone(DEFAULT);fresh.shipData.courier=normalizeShipRecord(null,'courier',fresh);return fresh}}
function syncActiveShipData(){if(!state?.activeShip)return;state.shipData=state.shipData||{};state.shipData[state.activeShip]={condition:state.condition,fuel:state.fuel,upgrades:structuredClone(state.upgrades)}}
function save(){syncActiveShipData();state.reputation=Math.max(0,Math.min(100,Math.round(state.reputation)));updateCreditNegativity();localStorage.setItem("cosmicCargoSave",JSON.stringify(state));updateHeader()}
function updateHeader(){const credit=$('#credits'),negativeRemaining=state.credits<0&&state.negativeCreditSince?Math.max(0,NEGATIVE_CREDIT_LIMIT_MS-(Date.now()-state.negativeCreditSince)):0;credit.textContent=state.credits.toLocaleString('pt-BR')+' CR'+(negativeRemaining?` · ${Math.ceil(negativeRemaining/86400000)}d`:'' );credit.classList.toggle('fuel-bad',state.credits<0);credit.title=state.credits<0?(GAME_LANGUAGE==='en-US'?'Return to a positive balance within three days to avoid bankruptcy.':'Volte ao saldo positivo em até três dias para evitar a falência.'):'';$('#headerFuel').textContent=Math.round(state.fuel)+' / '+shipFuel()+' u';$('#reputation').textContent=state.reputation+' / 100 · N'+unlockedContractLevel();$('#cargoBadge').textContent=state.accepted.length;const go=$('#goToCargo');if(go){const count=state.accepted.length,destination=acceptedCargo()[0]?.destination;go.disabled=!count;go.textContent=count?`Acondicionar ${count} encomenda${count>1?'s':''} para ${destination} →`:'Selecione ao menos um contrato'}}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2400)}
const NEGATIVE_CREDIT_LIMIT_MS=3*24*60*60*1000;
function updateCreditNegativity(){if(!state?.careerStarted)return;if(state.credits<0){if(!Number.isFinite(state.negativeCreditSince))state.negativeCreditSince=Date.now()}else state.negativeCreditSince=null}
function checkCreditBankruptcy(){updateCreditNegativity();if(!state?.careerStarted||state.credits>=0||!state.negativeCreditSince||Date.now()-state.negativeCreditSince<NEGATIVE_CREDIT_LIMIT_MS)return false;const modal=$('#shipPurchaseModal'),content=$('#shipPurchaseContent');if(!modal||!content||modal.dataset.bankruptcy==='1')return true;modal.dataset.bankruptcy='1';content.innerHTML=`<h2>${GAME_LANGUAGE==='en-US'?'Company bankrupt':'Falência da transportadora'}</h2><p>${GAME_LANGUAGE==='en-US'?'The company remained with a negative balance for more than three days. The pilot career has ended.':'A empresa permaneceu com saldo negativo por mais de três dias. A carreira de piloto foi encerrada.'}</p><button id="restartAfterBankruptcy" class="danger">${GAME_LANGUAGE==='en-US'?'Start a new career':'Iniciar nova carreira'}</button>`;modal.classList.remove('hidden');$('#restartAfterBankruptcy').onclick=()=>{modal.dataset.bankruptcy='';modal.classList.add('hidden');newCareer()};return true}
function rng(seed){let a=seed|0;return()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function emergencyContract(destination){if(!destination)return null;const d=DESTINATIONS[destination],mass=20+(state.boardSeed%13),distanceFactor=Math.log10(d.km/384400+1),hiddenReward=regionalFreightValue(d.rewardBase?Math.round((d.rewardBase+mass*42+d.risk*850)/100)*100:Math.round((420+distanceFactor*480+mass*5+d.risk*55)/10)*10);return{id:`emergency-${state.boardSeed}-${destination}`,client:'Sindicato de Transporte Galático',cargo:d.emergency,destination,mass,volume:1,type:'emergency',reward:0,hiddenReward,emergency:true}}
function unlockedContractLevel(){return Math.min(5,1+Math.floor(Math.max(0,Math.min(100,state?.reputation??25))/25))}
function contractLevelName(level){return['','REGULAR','PRIORITÁRIA','ESPECIALISTA','CONFIDENCIAL','DIPLOMÁTICA'][level]}
function contracts(){const r=rng(state.boardSeed),out=[],unlocked=unlockedContractLevel();Object.entries(DESTINATIONS).forEach(([destination,d],di)=>{const count=3+Math.floor(r()*3),distanceFactor=Math.log10(d.km/384400+1);for(let i=0;i<count;i++){const cargo=d.cargo[Math.floor(r()*d.cargo.length)],type=r()<.32?'fragile':r()<.58?'heavy':'standard',volume=type==='heavy'?2+Math.floor(r()*2):1+Math.floor(r()*2),mass=Math.round((type==='heavy'?52:14)+r()*(type==='heavy'?36:34)),level=1+Math.floor(r()*unlocked),baseReward=d.rewardBase?d.rewardBase+Math.round((mass*42+d.risk*850+r()*6000)/100)*100:Math.round((420+distanceFactor*480+mass*5+d.risk*55)/10)*10,reward=regionalFreightValue(Math.round(baseReward*(1+(level-1)*.35)/10)*10);out.push({id:`${state.boardSeed}-${di}-${i}`,client:d.clients[Math.floor(r()*d.clients.length)],cargo,destination,mass,volume,type,level,reward})}});const emergency=emergencyContract(state.emergencyDestination);if(emergency)out.unshift(emergency);return out}
function nav(view){$$('.view,.nav button').forEach(e=>e.classList.remove('active'));$('#'+view).classList.add('active');const button=$(`.nav button[data-view="${view}"]`);if(button)button.classList.add('active');if(view==='cargo')renderCargo();if(view==='controls')renderInputSettings();if(['hangar','workshop','refueling','dealership'].includes(view))renderGarage()}
$$('.nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));
$('#goToCargo').onclick=()=>nav('cargo');
function shipFuel(){const ship=SHIPS[state.activeShip];return ship.fuel+state.upgrades.tank*ship.tankStep}
function shipSlots(){return SHIPS[state.activeShip].slots}
function fuelPrice(shipKey=state.activeShip){const ship=typeof shipKey==='string'?SHIPS[shipKey]:shipKey,tier=ship?.tier||1;return tier>=5?2:tier===4?1.5:tier===3?1.2:1}
function fuelClass(shipKey=state.activeShip){const ship=typeof shipKey==='string'?SHIPS[shipKey]:shipKey,tier=ship?.tier||1,english=GAME_LANGUAGE==='en-US';if(tier>=5)return english?'High-energy fuel':'Combustível de alta energia';if(tier===4)return english?'Advanced fuel':'Combustível avançado';if(tier===3)return english?'Refined fuel':'Combustível refinado';return english?'Simple fuel':'Combustível simples'}
function acceptedCargo(extra){return [...state.accepted,...(extra?[extra]:[])].map(id=>contracts().find(c=>c.id===id)).filter(Boolean)}
function tripFuel(list=acceptedCargo()){if(!list.length)return 0;const d=DESTINATIONS[list[0].destination],mass=list.reduce((n,c)=>n+c.mass,0);return Math.round(d.travel+mass*(1.15+d.risk*.14))}
function contractBlockReason(c){const current=acceptedCargo(),d=DESTINATIONS[c.destination],ship=SHIPS[state.activeShip];if(!shipCanReachDestination(state.activeShip,c.destination))return`Exige nave categoria ${d.requiredTier||1}`;if(current[0]&&current[0].destination!==c.destination)return'Destino diferente';const candidate=[...current,c];if(!current.length&&((state.landings||0)+1)%3===0){const emergency=emergencyContract(c.destination);if(emergency)candidate.push(emergency)}if(candidate.reduce((n,x)=>n+x.volume,0)>shipSlots())return'Sem espaços disponíveis';if(candidate.reduce((n,x)=>n+x.mass,0)>ship.mass+state.upgrades.hold*30*ship.tier)return'Limite de massa';if(tripFuel(candidate)>state.fuel-150)return'Combustível insuficiente';return''}
function canAdd(c){return!contractBlockReason(c)}
