function buyFuel(amount){const missing=Math.max(0,shipFuel()-state.fuel),units=Math.max(0,Math.min(missing,Math.floor(amount||0))),cost=Math.round(units*fuelPrice());if(!units)return;if(cost>state.credits)return toast(`Créditos insuficientes. O abastecimento custa ${cost.toLocaleString('pt-BR')} CR.`);state.credits-=cost;state.fuel+=units;save();renderGarage();renderContracts();renderCargo();toast(`${units} unidades de combustível adicionadas.`)}
