function activateShip(k){if(!SHIPS[k]||!state.ownedShips.includes(k)||k===state.activeShip)return;if(state.accepted.length)return toast('Cancele ou conclua os contratos atuais antes de trocar de nave.');if(state.afk?.journeys?.some(j=>j.shipKey===k))return toast('Esta nave está em uma viagem automática. Aguarde o retorno.');syncActiveShipData();const data=state.shipData[k]||normalizeShipRecord(null,k);state.activeShip=k;state.condition=data.condition;state.fuel=data.fuel;state.upgrades=structuredClone(data.upgrades);state.slots=Array(SHIPS[k].slots).fill(null);state.cargoRotations={};selectedSlot=null;save();renderGarage();renderContracts();renderCargo();toast(`${SHIPS[k].name} agora é a nave ativa.`)}
function shipTradeValueFor(key){const ship=SHIPS[key],data=key===state.activeShip?{condition:state.condition}:state.shipData[key];return ship?Math.max(0,Math.round(ship.price*.45*((data?.condition??100)/100)/100)*100):0}
