function renderDealershipOptions(){const owned=state.ownedShips||[],traded=state.tradedShips||[],activeShip=SHIPS[state.activeShip],tradeValue=shipTradeValue();$('#shipShop').innerHTML=Object.entries(SHIPS).map(([k,s])=>{const isOwned=owned.includes(k),wasTraded=traded.includes(k),previousOwned=s.tier===1||wasTraded||owned.some(o=>SHIPS[o].tier===s.tier-1),locked=!isOwned&&!previousOwned,canTrade=!isOwned&&!locked&&k!==state.activeShip&&s.tier>activeShip.tier,tax=shipPurchaseTax(s),fullCost=s.price+tax,tradeCost=Math.max(0,s.price-tradeValue)+tax,description=k==='courier'?'Nave inicial com casco reforçado e 25% de resistência ao dano de pouso.':k==='hauler'?'Maior tanque, carga e tecnologia de controle.':'Maior desempenho, autonomia e precisão da frota.',status=wasTraded?'<p class="trade-note">Entregue anteriormente em troca. A recompra cria uma nova unidade, sem as melhorias antigas.</p>':'';let actions;if(isOwned)actions='<button class="secondary" disabled>Já está no Hangar</button>';else if(locked)actions=`<button class="secondary" disabled>Exige nave categoria ${s.tier-1}</button>`;else actions=`<button class="primary" data-buy-ship="${k}" data-trade-mode="full">Comprar por ${fullCost.toLocaleString('pt-BR')} CR · imposto ${tax.toLocaleString('pt-BR')}</button>${canTrade?`<button class="secondary" data-buy-ship="${k}" data-trade-mode="trade">Entregar ${activeShip.name} · pagar ${tradeCost.toLocaleString('pt-BR')} CR · imposto ${tax.toLocaleString('pt-BR')}</button>`:''}`;return`<article class="dealership-card ${locked?'locked':''}"><div class="dealership-visual">${shipArt(s)}</div><div><span class="eyebrow">CATEGORIA ${s.tier}</span><h2>${s.name}</h2><p>${description}</p><p>${s.slots} espaços · ${s.mass} kg · tanque-base de ${s.fuel} u</p>${status}<strong>Total sem troca: ${fullCost.toLocaleString('pt-BR')} CR</strong><small>Preço ${s.price.toLocaleString('pt-BR')} + imposto ${tax.toLocaleString('pt-BR')} CR</small></div><div class="dealership-actions">${actions}</div></article>`}).join('');$$('[data-buy-ship]').forEach(b=>b.onclick=()=>buyShip(b.dataset.buyShip,b.dataset.tradeMode==='trade'))}
const renderGarageBase=renderGarage;renderGarage=()=>{renderGarageBase();renderDealershipOptions();markUnaffordable()};
function buyShip(k,tradeIn=false){const newShip=SHIPS[k],owned=state.ownedShips||[],traded=state.tradedShips||[];if(!newShip||owned.includes(k))return;if(state.accepted.length)return toast('Cancele ou conclua os contratos atuais antes de comprar uma nave.');const previousOwned=newShip.tier===1||traded.includes(k)||owned.some(o=>SHIPS[o].tier===newShip.tier-1);if(!previousOwned)return toast(`Compre primeiro uma nave da categoria ${newShip.tier-1}.`);const oldKey=state.activeShip,oldShip=SHIPS[oldKey],validTrade=tradeIn&&k!==oldKey&&newShip.tier>oldShip.tier;if(tradeIn&&!validTrade)return toast('Esta nave não pode receber a nave ativa como parte do pagamento.');if(validTrade&&state.afk?.employees?.some(e=>e.shipKey===oldKey))return toast('Retire esta nave da escala dos funcionários antes de entregá-la na troca.');const tradeValue=validTrade?shipTradeValue():0,tax=shipPurchaseTax(newShip),cost=Math.max(0,newShip.price-tradeValue)+tax;if(cost>state.credits)return toast(`Créditos insuficientes. O total com imposto é ${cost.toLocaleString('pt-BR')} CR.`);syncActiveShipData();state.credits-=cost;if(validTrade){state.ownedShips=owned.filter(id=>id!==oldKey);state.tradedShips=[...new Set([...traded,oldKey])];delete state.shipData[oldKey]}else state.ownedShips=[...owned];state.ownedShips=[...new Set([...state.ownedShips,k])];state.tradedShips=(state.tradedShips||[]).filter(id=>id!==k);state.shipData[k]=normalizeShipRecord(null,k,{condition:100,fuel:0,upgrades:structuredClone(DEFAULT.upgrades)});state.activeShip=k;state.condition=100;state.fuel=0;state.upgrades=structuredClone(DEFAULT.upgrades);state.slots=Array(newShip.slots).fill(null);state.cargoRotations={};selectedSlot=null;save();renderGarage();renderContracts();renderCargo();showShipPurchase(newShip,validTrade,oldShip,tradeValue,cost,tax)}
function showShipPurchase(newShip,tradeIn=false,oldShip=null,tradeValue=0,cost=newShip.price,tax=shipPurchaseTax(newShip)){const modal=$('#shipPurchaseModal'),content=$('#shipPurchaseContent'),message=tradeIn?`A ${oldShip.name} foi entregue como parte do pagamento e removida do Hangar. Para utilizá-la novamente, será necessário comprá-la outra vez; suas melhorias, combustível e integridade anteriores não são recuperados.`:'A nova nave foi adicionada ao Hangar e já está ativa. Suas outras naves, melhorias, combustível e integridade foram preservados.',breakdown=`<p><span>Preço da nave</span><b>${newShip.price.toLocaleString('pt-BR')} CR</b></p><p><span>Imposto de compra · ${economyPercent(ECONOMY.shipTax)}</span><b>${tax.toLocaleString('pt-BR')} CR</b></p>${tradeIn?`<p><span>Desconto pela ${oldShip.name}</span><b>− ${tradeValue.toLocaleString('pt-BR')} CR</b></p>`:''}<p><span>Total pago</span><b>${cost.toLocaleString('pt-BR')} CR</b></p>`;content.innerHTML=`<span class="eyebrow">COMPRA CONCLUÍDA</span><h2 id="purchaseTitle">Você comprou a nave ${newShip.name}</h2><p>${message}</p><div class="purchase-breakdown">${breakdown}<p><span>Naves disponíveis no Hangar</span><b>${state.ownedShips.length}</b></p></div><button id="continueAfterPurchase" class="primary">Ir para o Hangar</button>`;modal.classList.remove('hidden');$('#continueAfterPurchase').onclick=()=>{modal.classList.add('hidden');nav('hangar')}}
