$('#mainMenuBtn').onclick=returnToMainMenu;$('#restartCareerBtn').onclick=confirmRestartCareer;$('#resetSave').onclick=confirmRestartCareer;const refreshContractBoard=()=>{if(state.credits<40)return toast('Créditos insuficientes.');if(state.accepted.length)return toast('Recuse os contratos atuais antes de atualizar.');state.credits-=40;state.boardSeed++;save();renderContracts();toast('Novo quadro gerado para esta rodada.')};$('#refreshContracts').onclick=refreshContractBoard;$('#refreshContractsBottom').onclick=refreshContractBoard;
