const STAFF_LEVELS={1:{hire:4800,commission:.18,fuel:1.08,shipDamage:1.14,cargoDamage:1.12,speed:1},2:{hire:13500,commission:.22,fuel:.95,shipDamage:.89,cargoDamage:.87,speed:.88},3:{hire:31000,commission:.27,fuel:.83,shipDamage:.68,cargoDamage:.66,speed:.76}};
const STAFF_SKILLS={economy:{name:'Gestão de combustível',desc:'Reduz o consumo da nave.'},piloting:{name:'Pilotagem defensiva',desc:'Reduz danos e consertos.'},cargo:{name:'Proteção de carga',desc:'Reduz avarias nas encomendas.'},speed:{name:'Navegação de rota',desc:'Reduz o tempo de ida e volta.'}};
const STAFF_SEEDS=[
  {id:'lia',name:'Lia Moura',level:1,trait:'economy',hireMod:.96,commissionMod:.01,history:'Ex-técnica de mineração lunar. Conhece cada ruído de um motor antigo e economiza combustível em rotas curtas.'},
  {id:'bento',name:'Bento Arantes',level:1,trait:'cargo',hireMod:1.04,commissionMod:-.01,history:'Carregador orbital promovido a piloto. Sua experiência no convés protege encomendas frágeis.'},
  {id:'yara',name:'Yara Okafor',level:2,trait:'piloting',hireMod:1.08,commissionMod:-.01,history:'Veterana das tempestades marcianas. Mantém a nave estável em aproximações de alto risco.'},
  {id:'caio',name:'Caio Venn',level:2,trait:'speed',hireMod:.94,commissionMod:.015,history:'Navegador de comboios venusianos. Planeja janelas rápidas sem ultrapassar os limites da tripulação.'},
  {id:'nyx',name:'Nyx Tanaka',level:3,trait:'economy',hireMod:1.02,commissionMod:-.015,history:'Comandante das rotas de Titã. Une precisão, autonomia e disciplina operacional.'}
];
const STAFF_REPLACEMENTS=['Amina Sol','Davi Kessler','Iris Volkov','Mateo Quill','Noa Sato','Ravi Anders','Selene Costa','Téo Nadir'];
const AUTO_ROUTE_HOURS={Lua:2.5,Marte:8,Europa:11,'Vênus':6,'Titã':14};
function freshSkills(){return{economy:0,piloting:0,cargo:0,speed:0}}
function staffCandidate(seed){return{...seed,skills:freshSkills(),trainingSpent:0,commissionBonus:0}}
function ensureAFK(){if(!state.afk||typeof state.afk!=='object')state.afk={enabled:true,candidates:STAFF_SEEDS.map(staffCandidate),employees:[],journeys:[],log:[],totalNet:0,totalGross:0,lastMoodTick:Date.now(),replacementIndex:0};const a=state.afk;a.enabled=a.enabled!==false;a.candidates=Array.isArray(a.candidates)?a.candidates:STAFF_SEEDS.map(staffCandidate);a.employees=Array.isArray(a.employees)?a.employees:[];a.journeys=Array.isArray(a.journeys)?a.journeys:[];a.log=Array.isArray(a.log)?a.log:[];a.totalNet=Number(a.totalNet)||0;a.totalGross=Number(a.totalGross)||0;a.lastMoodTick=Number(a.lastMoodTick)||Date.now();a.replacementIndex=Number(a.replacementIndex)||0;a.employees.forEach(e=>{e.skills={...freshSkills(),...(e.skills||{})};e.mood=Number.isFinite(e.mood)?e.mood:100;e.shift=e.shift||'day';e.status=e.status||'idle';e.workHours=Number(e.workHours)||0;e.workDay=e.workDay||'';e.trainingSpent=Number(e.trainingSpent)||0;e.commissionBonus=Number(e.commissionBonus)||0})}
function afkUnlocked(){return state.ownedShips.some(k=>SHIPS[k]?.tier>=4)}
function eligibleAFKShips(){return state.ownedShips.filter(k=>SHIPS[k]&&SHIPS[k].tier<=3)}
function staffHireCost(e){return Math.round(STAFF_LEVELS[e.level].hire*(e.hireMod||1)/50)*50}
function staffStats(e){const base=STAFF_LEVELS[e.level],next=STAFF_LEVELS[e.level+1],progress=k=>(e.skills[k]||0)/4,target=(key,lower=true)=>{const start=base[key],finish=next?next[key]*(lower?.97:1.03):start*(lower?.8:1.2);return start+(finish-start)*progress(key)},trait=e.trait;let fuel=target('fuel'),shipDamage=target('shipDamage'),cargoDamage=target('cargoDamage'),speed=target('speed'),commission=Math.max(.08,base.commission+(e.commissionMod||0)-(e.skills.economy||0)*.006+e.commissionBonus);if(trait==='economy')fuel*=.94;if(trait==='piloting')shipDamage*=.92;if(trait==='cargo')cargoDamage*=.9;if(trait==='speed')speed*=.92;return{fuel,shipDamage,cargoDamage,speed,commission}}
function staffTrainingCost(e,key){const next=(e.skills[key]||0)+1,base=700*e.level*(e.hireMod||1);return Math.round(base*[1,1.55,2.25,3.4][next-1]/50)*50}
function severanceCost(e){return LABOR_POLICY.severance?Math.round((staffHireCost(e)*.45+e.trainingSpent*.7)/50)*50:0}
function staffTraitName(key){return STAFF_SKILLS[key]?.name||key}
function staffStatus(e,now=Date.now()){const trip=state.afk.journeys.find(j=>j.employeeId===e.id);if(trip)return`Em viagem para ${trip.destination} · retorna ${formatAFKTime(trip.endAt)}`;if(e.negotiationPending)return'Renegociação pendente';if(e.awayUntil>now)return`${e.awayType==='vacation'?'Férias':'Folga'} até ${formatAFKTime(e.awayUntil)}`;if(!e.shipKey)return'Aguardando designação de nave';if(!state.afk.enabled)return'Viagens automáticas encerradas';return'Aguardando turno ou contrato'}
function formatAFKTime(value){return new Date(value).toLocaleString(GAME_LANGUAGE,{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function shiftOpen(e,date=new Date()){const day=date.getDay(),hour=date.getHours()+date.getMinutes()/60;if(e.shift==='night'){const shiftDay=hour<6?new Date(date.getTime()-86400000).getDay():day;return shiftDay>=1&&shiftDay<=5&&(hour>=22||hour<6)}return day>=1&&day<=5&&hour>=8&&hour<16}
function workDayKey(e,date=new Date()){const adjusted=e.shift==='night'&&date.getHours()<6?new Date(date.getTime()-86400000):date;return`${adjusted.getFullYear()}-${adjusted.getMonth()}-${adjusted.getDate()}`}
function employeeCanDispatch(e,now){if(e.status==='traveling'||e.negotiationPending||!e.shipKey||e.awayUntil>now||!shiftOpen(e,new Date(now)))return false;const key=workDayKey(e,new Date(now));if(e.workDay!==key){e.workDay=key;e.workHours=0}return e.workHours<8}
function afkShipRecord(key){return state.shipData[key]||normalizeShipRecord(null,key)}
function setAFKShipRecord(key,record){state.shipData[key]=record;if(state.activeShip===key){state.condition=record.condition;state.fuel=record.fuel;state.upgrades=structuredClone(record.upgrades)}}
function chooseAFKContract(e,shipKey){const ship=SHIPS[shipKey],list=contracts().filter(c=>!c.emergency&&c.level<=e.level&&!isExtrasolarDestination(c.destination)&&c.volume<=ship.slots&&c.mass<=ship.mass);if(!list.length)return null;const seed=Math.abs((Date.now()/60000|0)+e.id.split('').reduce((n,c)=>n+c.charCodeAt(0),0));return list[seed%list.length]}
function dispatchAFK(e,now=Date.now()){const shipKey=e.shipKey;if(shipKey===state.activeShip&&state.accepted.length)return false;const record=afkShipRecord(shipKey),contract=chooseAFKContract(e,shipKey);if(!contract||record.condition<20)return false;const stats=staffStats(e),baseFuel=tripFuel([contract]),fuel=Math.max(1,Math.round(baseFuel*stats.fuel));if(record.fuel<fuel)return false;const hours=(AUTO_ROUTE_HOURS[contract.destination]||8)*stats.speed,endAt=now+hours*3600000,night=e.shift==='night';record.fuel-=fuel;setAFKShipRecord(shipKey,record);e.status='traveling';state.afk.journeys.push({id:`auto-${now}-${e.id}`,employeeId:e.id,shipKey,contractId:contract.id,destination:contract.destination,cargo:contract.cargo,level:contract.level,reward:contract.reward,fuel,hours,night,startedAt:now,endAt});return true}
function completeAFKJourney(j,now){const e=state.afk.employees.find(x=>x.id===j.employeeId),ship=SHIPS[j.shipKey],record=afkShipRecord(j.shipKey);if(!e||!ship)return;const stats=staffStats(e),risk=DESTINATIONS[j.destination].risk,shipDamage=Math.min(32,Math.max(.4,(1.1+risk*.72)*(0.75+Math.random()*.5)*stats.shipDamage)),cargoDamage=Math.min(55,Math.max(0,(risk*1.05-1.5)*(0.65+Math.random()*.7)*stats.cargoDamage)),basePayout=Math.round(j.reward*(1-cargoDamage/100)),nightBonus=j.night?Math.round(basePayout*LABOR_POLICY.nightBonus):0,gross=basePayout+nightBonus,overtime=Math.max(0,j.hours-8),commission=Math.round(gross*stats.commission*(1+(overtime/j.hours)*.5)),benefits=0,repair=Math.round(ship.repair*shipDamage/100),fuelCost=j.fuel*fuelPrice(),net=gross-commission-benefits-repair-fuelCost;record.condition=Math.max(20,record.condition-shipDamage);record.condition=Math.min(100,record.condition+shipDamage);setAFKShipRecord(j.shipKey,record);state.credits+=gross-commission-benefits-repair;state.afk.totalGross+=gross;state.afk.totalNet+=net;e.status='idle';e.workHours=(e.workHours||0)+j.hours;e.mood=Math.max(0,e.mood-4-j.hours*.45);if(e.mood<20)e.negotiationPending=true;state.afk.log.unshift({id:j.id,employee:e.name,ship:ship.name,destination:j.destination,cargo:j.cargo,endedAt:now,gross,commission,benefits,repair,fuelCost,net,shipDamage,cargoDamage,nightBonus,overtime});state.afk.log=state.afk.log.slice(0,30)}
function processAFK(forceRender=false){ensureAFK();const now=Date.now(),elapsedDays=Math.max(0,(now-state.afk.lastMoodTick)/86400000);if(elapsedDays>.01){state.afk.employees.forEach(e=>{if(!e.awayUntil||e.awayUntil<now)e.mood=Math.max(0,e.mood-elapsedDays*2)});state.afk.lastMoodTick=now}const finished=state.afk.journeys.filter(j=>j.endAt<=now);finished.forEach(j=>completeAFKJourney(j,j.endAt));if(finished.length)state.afk.journeys=state.afk.journeys.filter(j=>j.endAt>now);if(state.afk.enabled&&afkUnlocked()){const busyShips=new Set(state.afk.journeys.map(j=>j.shipKey));state.afk.employees.forEach(e=>{if(!busyShips.has(e.shipKey)&&employeeCanDispatch(e,now)&&dispatchAFK(e,now))busyShips.add(e.shipKey)})}if(finished.length||forceRender){save();renderAFK();renderGarage();renderContracts()}else save()}
function hireEmployee(id){ensureAFK();if(!afkUnlocked())return toast('Compre primeiro uma nave de categoria 4.');if(state.afk.employees.length>=5)return toast('O quadro já possui cinco funcionários.');const index=state.afk.candidates.findIndex(c=>c.id===id),candidate=state.afk.candidates[index];if(!candidate)return;const cost=staffHireCost(candidate);if(state.credits<cost)return toast('Créditos insuficientes para esta contratação.');state.credits-=cost;state.afk.candidates.splice(index,1);state.afk.employees.push({...candidate,mood:100,shift:'day',shipKey:'',status:'idle',hiredAt:Date.now(),workHours:0,workDay:''});save();renderAFK();toast(`${candidate.name} foi contratado(a).`)}
function trainEmployee(id,key){const e=state.afk.employees.find(x=>x.id===id);if(!e||!STAFF_SKILLS[key]||(e.skills[key]||0)>=4||e.status==='traveling')return;const cost=staffTrainingCost(e,key);if(state.credits<cost)return toast('Créditos insuficientes para o treinamento.');state.credits-=cost;e.skills[key]++;e.trainingSpent+=cost;save();renderAFK()}
function assignEmployee(id,shipKey){const e=state.afk.employees.find(x=>x.id===id);if(!e||e.status==='traveling')return;if(shipKey&&!eligibleAFKShips().includes(shipKey))return toast('Funcionários utilizam apenas naves das categorias 1 a 3.');e.shipKey=shipKey;save();renderAFK();processAFK(true)}
function setEmployeeShift(id,shift){const e=state.afk.employees.find(x=>x.id===id);if(!e||e.status==='traveling'||!['day','night'].includes(shift))return;e.shift=shift;save();renderAFK()}
function giveStaffLeave(id,type){const e=state.afk.employees.find(x=>x.id===id);if(!e||e.status==='traveling')return;const duration=type==='vacation'?7*86400000:24*3600000,gain=type==='vacation'?60:18;e.awayUntil=Date.now()+duration;e.awayType=type;e.mood=Math.min(100,e.mood+gain);save();renderAFK()}
function replacementCandidate(level,sourceName){const i=state.afk.replacementIndex++,name=STAFF_REPLACEMENTS[i%STAFF_REPLACEMENTS.length],trait=Object.keys(STAFF_SKILLS)[i%4];return staffCandidate({id:`replacement-${Date.now()}-${i}`,name,level,trait,hireMod:.94+(i%4)*.04,commissionMod:[.01,-.01,.015,-.015][i%4],history:`${name} assumiu a vaga de ${sourceName}. Traz experiência de nível ${level}, mas inicia sem treinamentos específicos.`})}
function removeEmployee(id,voluntary=false){const e=state.afk.employees.find(x=>x.id===id);if(!e||e.status==='traveling')return;const cost=voluntary?0:severanceCost(e);if(!voluntary&&state.credits<cost)return toast('Créditos insuficientes para pagar a multa rescisória.');if(!voluntary&&!confirm(`Demitir ${e.name} e pagar ${cost.toLocaleString('pt-BR')} CR de multa rescisória?`))return;state.credits-=cost;state.afk.employees=state.afk.employees.filter(x=>x.id!==id);state.afk.candidates.push(replacementCandidate(e.level,e.name));save();renderAFK();toast(voluntary?`${e.name} pediu demissão. Um novo candidato está disponível.`:`${e.name} foi desligado(a).`)}
function negotiateEmployee(id,accept){const e=state.afk.employees.find(x=>x.id===id);if(!e?.negotiationPending)return;if(!accept)return removeEmployee(id,true);e.commissionBonus+=.05;e.mood=55;e.negotiationPending=false;save();renderAFK();toast(`Novo contrato de ${e.name}: comissão acrescida em 5 pontos percentuais.`)}
function renderAFK(){ensureAFK();const unlocked=afkUnlocked(),a=state.afk,now=Date.now(),ships=eligibleAFKShips();$('#automaticLock').innerHTML=unlocked?'':`<div class="locked-panel"><h2>Central bloqueada</h2><p>Compre uma nave de categoria 4 para liberar contratações e viagens automáticas. Os funcionários poderão operar somente naves das categorias 1, 2 e 3.</p></div>`;$('#toggleAutomatic').disabled=!unlocked;$('#toggleAutomatic').textContent=a.enabled?'Encerrar viagens automáticas':'Retomar viagens automáticas';$('#toggleAutomatic').className=a.enabled?'danger':'primary';$('#automaticSummary').innerHTML=`<span><small>OPERAÇÃO</small><b>${a.enabled?'ATIVA':'ENCERRADA'}</b></span><span><small>EM VIAGEM</small><b>${a.journeys.length}</b></span><span><small>EQUIPE</small><b>${a.employees.length}/5</b></span><span><small>LUCRO LÍQUIDO ACUMULADO</small><b class="${a.totalNet>=0?'fuel-ok':'fuel-bad'}">${Math.round(a.totalNet).toLocaleString('pt-BR')} CR</b></span>`;$('#crewHeading').classList.toggle('hidden',!unlocked);$('#candidatesHeading').classList.toggle('hidden',!unlocked);$('#crewGrid').innerHTML=unlocked?(a.employees.length?a.employees.map(e=>staffCard(e,ships,now)).join(''):'<p class="empty-state">Nenhum funcionário contratado.</p>'):'';$('#candidateGrid').innerHTML=unlocked?(a.candidates.length?a.candidates.map(candidateCard).join(''):'<p class="empty-state">Não há candidatos no momento.</p>'):'';$('#automaticLog').innerHTML=a.log.length?a.log.map(l=>`<article class="trip-log"><div><b>${l.employee} · ${l.destination}</b><small>${l.ship} · ${l.cargo} · ${formatAFKTime(l.endedAt)}</small></div><div class="trip-economy"><span>Frete ${l.gross.toLocaleString('pt-BR')}</span><span>Comissão −${l.commission.toLocaleString('pt-BR')}</span><span>Benefícios −${l.benefits.toLocaleString('pt-BR')}</span><span>Combustível −${l.fuelCost.toLocaleString('pt-BR')}</span><span>Conserto −${l.repair.toLocaleString('pt-BR')}</span><b class="${l.net>=0?'fuel-ok':'fuel-bad'}">Líquido ${l.net.toLocaleString('pt-BR')} CR</b></div><small>Danos: nave ${l.shipDamage.toFixed(1)}% · carga ${l.cargoDamage.toFixed(1)}%${l.nightBonus?` · adicional noturno ${l.nightBonus.toLocaleString('pt-BR')} CR`:''}${l.overtime?` · ${l.overtime.toFixed(1)} h extras`:''}</small></article>`).join(''):'<p class="empty-state">As viagens concluídas aparecerão aqui com todos os custos e o lucro líquido.</p>';bindAFKControls()}
function candidateCard(c){const s=staffStats(c),hire=staffHireCost(c);return`<article class="staff-card candidate"><div class="staff-title"><div><span class="eyebrow">PILOTO NÍVEL ${c.level}</span><h2>${c.name}</h2></div><span class="staff-level">N${c.level}</span></div><p>${c.history}</p><p><b>Especialidade:</b> ${staffTraitName(c.trait)}</p><div class="staff-metrics"><span>Consumo<b>×${s.fuel.toFixed(2)}</b></span><span>Dano nave<b>×${s.shipDamage.toFixed(2)}</b></span><span>Dano carga<b>×${s.cargoDamage.toFixed(2)}</b></span><span>Comissão<b>${Math.round(s.commission*100)}%</b></span></div><button class="primary" data-hire="${c.id}">Contratar por ${hire.toLocaleString('pt-BR')} CR</button></article>`}
function staffCard(e,ships,now){const s=staffStats(e),traveling=e.status==='traveling',options='<option value="">Sem nave</option>'+ships.map(k=>`<option value="${k}" ${e.shipKey===k?'selected':''}>${SHIPS[k].name} · categoria ${SHIPS[k].tier}</option>`).join(''),negotiation=e.negotiationPending?`<div class="negotiation"><b>Renegociação obrigatória</b><p>Aceitar aumenta a comissão em 5 pontos percentuais. Recusar provoca demissão.</p><button class="primary" data-negotiate="accept" data-employee="${e.id}">Aceitar</button><button class="danger" data-negotiate="refuse" data-employee="${e.id}">Recusar</button></div>`:'';return`<article class="staff-card employed"><div class="staff-title"><div><span class="eyebrow">PILOTO NÍVEL ${e.level}</span><h2>${e.name}</h2></div><span class="mood ${e.mood<20?'critical':e.mood<50?'warning':''}">${Math.round(e.mood)}/100</span></div><p>${e.history}</p><p class="staff-state">${staffStatus(e,now)}</p><div class="staff-metrics"><span>Consumo<b>×${s.fuel.toFixed(2)}</b></span><span>Dano nave<b>×${s.shipDamage.toFixed(2)}</b></span><span>Dano carga<b>×${s.cargoDamage.toFixed(2)}</b></span><span>Comissão<b>${Math.round(s.commission*100)}%</b></span></div><div class="staff-controls"><label>Nave<select data-assign="${e.id}" ${traveling?'disabled':''}>${options}</select></label><label>Turno<select data-shift="${e.id}" ${traveling?'disabled':''}><option value="day" ${e.shift==='day'?'selected':''}>Diurno · 8h–16h</option><option value="night" ${e.shift==='night'?'selected':''}>${GAME_LANGUAGE==='en-US'?'Night · 10 PM–6 AM · no statutory premium':`Noturno · 22h–6h (+${Math.round(LABOR_POLICY.nightBonus*100)}%)`}</option></select></label></div>${negotiation}<div class="staff-training">${Object.entries(STAFF_SKILLS).map(([k,v])=>{const level=e.skills[k]||0,max=level>=4,cost=staffTrainingCost(e,k);return`<div><span><b>${v.name}</b><small>${v.desc}</small></span><button class="${max?'secondary':'primary'}" data-train="${k}" data-employee="${e.id}" ${max||traveling?'disabled':''}>${max?'Máximo':`N${level+1} · ${cost.toLocaleString('pt-BR')} CR`}</button></div>`}).join('')}</div><div class="staff-actions"><button class="secondary" data-leave="day" data-employee="${e.id}" ${traveling?'disabled':''}>Dar folga</button><button class="secondary" data-leave="vacation" data-employee="${e.id}" ${traveling?'disabled':''}>Dar férias</button><button class="danger" data-fire="${e.id}" ${traveling?'disabled':''}>Demitir · multa ${severanceCost(e).toLocaleString('pt-BR')} CR</button></div></article>`}
function bindAFKControls(){$$('[data-hire]').forEach(b=>b.onclick=()=>hireEmployee(b.dataset.hire));$$('[data-train]').forEach(b=>b.onclick=()=>trainEmployee(b.dataset.employee,b.dataset.train));$$('[data-assign]').forEach(s=>s.onchange=()=>assignEmployee(s.dataset.assign,s.value));$$('[data-shift]').forEach(s=>s.onchange=()=>setEmployeeShift(s.dataset.shift,s.value));$$('[data-leave]').forEach(b=>b.onclick=()=>giveStaffLeave(b.dataset.employee,b.dataset.leave));$$('[data-fire]').forEach(b=>b.onclick=()=>removeEmployee(b.dataset.fire));$$('[data-negotiate]').forEach(b=>b.onclick=()=>negotiateEmployee(b.dataset.employee,b.dataset.negotiate==='accept'))}
const navBeforeAFK=nav;nav=view=>{navBeforeAFK(view);if(view==='automatic'){processAFK(true);renderAFK()}};$$('.nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('#toggleAutomatic').onclick=()=>{ensureAFK();state.afk.enabled=!state.afk.enabled;save();renderAFK();if(state.afk.enabled)processAFK(true)};
const newCareerBeforeAFK=newCareer;newCareer=()=>{newCareerBeforeAFK();ensureAFK();save();if($('#automatic'))renderAFK()};$('#newCareerBtn').onclick=newCareer;
ensureAFK();setTimeout(()=>processAFK(true),0);setInterval(()=>processAFK($('#automatic')?.classList.contains('active')||false),60000);

const MANAGER_CANDIDATES=[
  {id:'manager-1',name:'Helena Ward',level:1,cost:28000,moodLimit:35,leaveDiscount:0,history:'Coordenadora de tráfego lunar. Organiza a alternância das naves e concede folgas apenas em situações críticas.'},
  {id:'manager-2',name:'Omar Reyes',level:2,cost:62000,moodLimit:50,leaveDiscount:.1,history:'Especialista em escalas marcianas. Antecipa fadiga e reduz em 10% os custos administrativos de folgas.'},
  {id:'manager-3',name:'Mina Kwon',level:3,cost:110000,moodLimit:65,leaveDiscount:.2,history:'Diretora de operações interplanetárias. Mantém equipes descansadas e reduz em 20% os custos de folgas.'}
];
const MANAGER_SKILLS={
  scheduling:{name:'Planejamento de escalas',nameEn:'Shift planning',desc:'Antecipa folgas antes que o humor da equipe fique crítico.',descEn:'Schedules leave before crew morale becomes critical.'},
  wellbeing:{name:'Gestão de benefícios',nameEn:'Benefits management',desc:'Reduz o custo de folgas e férias em 5% por nível.',descEn:'Reduces leave and vacation costs by 5% per level.'},
  efficiency:{name:'Eficiência operacional',nameEn:'Operational efficiency',desc:'Reduz a comissão do gerente em 1 ponto percentual por nível.',descEn:'Reduces the manager commission by 1 percentage point per level.'}
};
function normalizeManager(manager){if(!manager)return null;manager.skills={scheduling:0,wellbeing:0,efficiency:0,...(manager.skills||{})};manager.hireCost=Number(manager.hireCost)||Number(manager.cost)||0;return manager}
function managerCommissionRate(){const manager=normalizeManager(state.afk?.manager);return manager?Math.max(.16,.20-(manager.skills.efficiency||0)*.01):0}
function managerMoodLimit(){const manager=normalizeManager(state.afk?.manager);return manager?Math.min(85,manager.moodLimit+(manager.skills.scheduling||0)*5):0}
function managerLeaveDiscount(){const manager=normalizeManager(state.afk?.manager);return manager?Math.min(.4,(manager.leaveDiscount||0)+(manager.skills.wellbeing||0)*.05):0}
function managerTrainingCost(skill){const manager=normalizeManager(state.afk?.manager),level=manager?.skills?.[skill]||0;return manager?Math.round(manager.hireCost*[.16,.24,.36,.52][level]/50)*50:0}
function managerSeveranceCost(){const manager=normalizeManager(state.afk?.manager);if(!manager||!LABOR_POLICY.severance)return 0;const training=Object.entries(manager.skills).reduce((total,[skill,level])=>{let spent=0;for(let index=0;index<level;index++)spent+=Math.round(manager.hireCost*[.16,.24,.36,.52][index]/50)*50;return total+spent},0);return Math.round((manager.hireCost*.5+training*.6)/50)*50}
const STAFF_AVERAGE_TRIP={1:1500,2:3000,3:5200};
function ensureAdvancedAFK(){ensureAFK();const a=state.afk;a.managerCandidates=Array.isArray(a.managerCandidates)?a.managerCandidates:structuredClone(MANAGER_CANDIDATES);a.manager=a.manager||null;a.loan=a.loan||null;a.shipOrders=a.shipOrders||{};a.lastCalendarProcess=Number(a.lastCalendarProcess)||Date.now();a.employees.forEach(e=>{e.workedDates=Array.isArray(e.workedDates)?e.workedDates:[];e.restUntil=Number(e.restUntil)||0;e.leaveStart=Number(e.leaveStart)||0;e.awayUntil=Number(e.awayUntil)||0});eligibleAFKShips().forEach(k=>{const assigned=a.employees.filter(e=>e.shipKey===k).map(e=>e.id),saved=(a.shipOrders[k]||[]).filter(id=>assigned.includes(id));a.shipOrders[k]=[...saved,...assigned.filter(id=>!saved.includes(id))]})}
function localDayKey(date){return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function weekendEnd(timestamp){const d=new Date(timestamp),day=d.getDay();if(day!==0&&day!==6)return timestamp;const add=day===6?2:1;d.setDate(d.getDate()+add);d.setHours(0,0,0,0);return d.getTime()}
function leaveCost(e,type){if(!LABOR_POLICY.paidLeave)return 0;const multiplier=type==='vacation'?40:1,discount=managerLeaveDiscount();return Math.round(STAFF_AVERAGE_TRIP[e.level]*multiplier*(1-discount)/50)*50}
function cumulativeLeaveStart(e,now){let start=Math.max(now,e.restUntil||0,e.awayUntil||0);start=weekendEnd(start);return start}
function staffStatusAdvanced(e,now=Date.now()){const trip=state.afk.journeys.find(j=>j.employeeId===e.id);if(trip)return`Em viagem para ${trip.destination} · retorna ${formatAFKTime(trip.endAt)}`;if(e.negotiationPending)return'Renegociação pendente';if(e.leaveStart>now)return`Afastamento agendado · começa ${formatAFKTime(e.leaveStart)}`;if(e.awayUntil>now){const remaining=e.awayUntil-now;return`${e.awayType==='vacation'?'Férias':'Folga'} · faltam ${formatDuration(remaining)}`};if(e.restUntil>now)return`Em descanso obrigatório · faltam ${formatDuration(e.restUntil-now)}`;const day=new Date(now).getDay();if(day===0||day===6)return`Final de semana · disponível ${formatAFKTime(weekendEnd(now))}`;if(!state.afk.enabled)return'Viagens automáticas encerradas';if(!e.shipKey)return'Aguardando designação de nave';return'Disponível'}
function formatDuration(ms){const days=Math.floor(ms/86400000),hours=Math.floor(ms%86400000/3600000),minutes=Math.max(0,Math.ceil(ms%3600000/60000));return days?`${days}d ${hours}h`:hours?`${hours}h ${minutes}min`:`${minutes}min`}
staffStatus=staffStatusAdvanced;
function employeeCanDispatchAdvanced(e,now){if(e.status==='traveling'||e.negotiationPending||!e.shipKey||e.leaveStart>now||e.awayUntil>now||!shiftOpen(e,new Date(now)))return false;if(e.restUntil>now)return false;if(e.restUntil&&e.restUntil<=now){e.restUntil=0;e.workHours=0}return(e.workHours||0)<8}
employeeCanDispatch=employeeCanDispatchAdvanced;
const dispatchAFKBeforeSchedule=dispatchAFK;dispatchAFK=(e,now=Date.now())=>{const started=dispatchAFKBeforeSchedule(e,now);if(started){const journey=state.afk.journeys.find(j=>j.employeeId===e.id&&j.startedAt===now),end=journey?.endAt||now;for(let cursor=new Date(now).setHours(0,0,0,0);cursor<=end;cursor+=86400000){const key=localDayKey(new Date(cursor));if(!e.workedDates.includes(key)){e.workedDates.push(key);e.mood=Math.max(0,e.mood-3)}}e.workedDates=e.workedDates.slice(-45)}return started};
function processMoodCalendar(now){const a=state.afk,last=new Date(a.lastCalendarProcess),today=new Date(now);last.setHours(0,0,0,0);today.setHours(0,0,0,0);for(let cursor=last.getTime();cursor<today.getTime();cursor+=86400000){const d=new Date(cursor),key=localDayKey(d),weekend=d.getDay()===0||d.getDay()===6;if(weekend)a.employees.forEach(e=>{if((e.hiredAt||0)<=cursor+86399999&&!e.workedDates.includes(key))e.mood=Math.min(100,e.mood+10)})}a.lastCalendarProcess=now;a.lastMoodTick=now}
function managerAdmin(now){const manager=normalizeManager(state.afk.manager);if(!manager)return;state.afk.employees.forEach(e=>{if(e.status==='traveling'||e.negotiationPending||e.awayUntil>now||e.leaveStart>now)return;if(e.mood<=managerMoodLimit()){const cost=leaveCost(e,'day');if(state.credits>=cost)giveStaffLeave(e.id,'day',true)}})}
function completeAFKJourneyAdvanced(j,now){const e=state.afk.employees.find(x=>x.id===j.employeeId),ship=SHIPS[j.shipKey],record=afkShipRecord(j.shipKey);if(!e||!ship)return;const stats=staffStats(e),risk=DESTINATIONS[j.destination].risk,shipDamage=Math.min(32,Math.max(.4,(1.1+risk*.72)*(0.75+Math.random()*.5)*stats.shipDamage)),cargoDamage=Math.min(55,Math.max(0,(risk*1.05-1.5)*(0.65+Math.random()*.7)*stats.cargoDamage)),basePayout=Math.round(j.reward*(1-cargoDamage/100)),nightBonus=j.night?Math.round(basePayout*LABOR_POLICY.nightBonus):0,gross=basePayout+nightBonus,tax=Math.round(gross*ECONOMY.freightTax),afterTax=gross-tax,loanPayment=state.afk.loan?Math.min(state.afk.loan.balance,Math.max(0,Math.round(gross*.10))):0,overtime=Math.max(0,j.hours-8),commission=Math.round(afterTax*stats.commission*(1+(overtime/j.hours)*.5)),benefits=0,fuelCost=j.fuel*fuelPrice(),repair=Math.round(ship.repair*shipDamage/100),operatingNet=afterTax-loanPayment-commission-benefits-fuelCost-repair,managerFee=state.afk.manager&&operatingNet>0?Math.round(operatingNet*managerCommissionRate()):0,net=operatingNet-managerFee,capacity=ship.fuel+(record.upgrades?.tank||0)*ship.tankStep;record.fuel=Math.min(capacity,record.fuel+j.fuel);record.condition=Math.max(20,record.condition-shipDamage);record.condition=Math.min(100,record.condition+shipDamage);setAFKShipRecord(j.shipKey,record);state.credits+=net;if(state.afk.loan)applyAutomaticLoanPayment(loanPayment);state.afk.totalGross+=gross;state.afk.totalNet+=net;e.status='idle';e.workHours=(e.workHours||0)+j.hours;if(e.workHours>=8)e.restUntil=now+16*3600000;if(e.mood<20)e.negotiationPending=true;state.afk.log.unshift({id:j.id,employee:e.name,ship:ship.name,destination:j.destination,cargo:j.cargo,endedAt:now,gross,tax,afterTax,commission,benefits,repair,fuelCost,managerFee,loanPayment,net,shipDamage,cargoDamage,nightBonus,overtime});state.afk.log=state.afk.log.slice(0,30)}
