const renderCargoBeforeStaging=renderCargo;renderCargo=()=>{clearCargoDragVisuals();renderCargoBeforeStaging();const accepted=acceptedCargo(),acceptedIds=new Set(accepted.map(c=>c.id)),placed=new Set(state.slots.filter(Boolean));state.stagedCargo=(state.stagedCargo||[]).filter(id=>acceptedIds.has(id)&&!placed.has(id));const staged=state.stagedCargo.map(id=>cargoFor(id)).filter(Boolean);$('#cargoStaging').innerHTML=staged.length?staged.map(c=>`<article class="staged-piece ${stagedCargoId===c.id?'selected':''}" data-staged="${c.id}" style="--cargo-color:${cargoColor(c.id)}"><div>${cargoShapePreview(c)}</div><span><b>${c.cargo}</b><small>${c.volume} slots · arraste a peça para a nave</small></span><button data-stage-rotate="${c.id}" ${c.volume===1?'disabled':''}>↻</button></article>`).join(''):'<p class="hint">Clique em “Carregar” no manifesto para trazer uma peça até a área externa.</p>';$$('[data-place]').forEach(b=>b.onclick=()=>{const id=b.dataset.place,first=state.slots.findIndex(x=>x===id);if(first>=0){selectedSlot=first;stagedCargoId=null}else{if(!state.stagedCargo.includes(id))state.stagedCargo.push(id);stagedCargoId=id}save();renderCargo()});$$('[data-staged]').forEach(card=>card.onclick=e=>{if(card.dataset.dragged==='1'||e.target.closest('button'))return;stagedCargoId=card.dataset.staged;selectedSlot=null;renderCargo()});$$('[data-stage-rotate]').forEach(b=>b.onclick=e=>{e.stopPropagation();rotateCargo(b.dataset.stageRotate)});$$('#cargoHold .slot').forEach(slot=>{const id=state.slots[+slot.dataset.slot];if(id)slot.style.setProperty('--cargo-color',cargoColor(id))});$$('#cargoHold .piece-cell').forEach(slot=>{slot.style.borderColor='var(--cargo-color)';slot.style.background=`color-mix(in srgb, var(--cargo-color) 22%, #0d2b40)`});bindCargoDragging()};

function bindCargoDragging(){$$('[data-staged]').forEach(card=>{card.onpointerdown=event=>{if(event.button!==0||event.target.closest('button'))return;const id=card.dataset.staged,startX=event.clientX,startY=event.clientY;let dragging=false,ghost=null,target=null;card.setPointerCapture?.(event.pointerId);const clearTarget=()=>{target?.classList.remove('drop-target');target=null};const move=moveEvent=>{if(!dragging&&Math.hypot(moveEvent.clientX-startX,moveEvent.clientY-startY)<7)return;if(!dragging){dragging=true;card.classList.add('drag-source');ghost=card.cloneNode(true);ghost.className='cargo-drag-ghost';ghost.querySelector('button')?.remove();document.body.appendChild(ghost)}moveEvent.preventDefault();ghost.style.transform=`translate3d(${moveEvent.clientX+14}px,${moveEvent.clientY+14}px,0)`;clearTarget();target=document.elementFromPoint(moveEvent.clientX,moveEvent.clientY)?.closest('#cargoHold .slot')||null;target?.classList.add('drop-target')};const finish=upEvent=>{card.onpointermove=null;card.onpointerup=null;card.onpointercancel=null;card.classList.remove('drag-source');ghost?.remove();clearTarget();if(!dragging)return;card.dataset.dragged='1';setTimeout(()=>delete card.dataset.dragged,0);const slot=document.elementFromPoint(upEvent.clientX,upEvent.clientY)?.closest('#cargoHold .slot');if(slot){const placed=placeCargo(id,+slot.dataset.slot,state.cargoRotations[id]||0,true);if(placed){state.stagedCargo=(state.stagedCargo||[]).filter(x=>x!==id);stagedCargoId=null;save()}}else toast('Arraste a peça até um espaço do compartimento da nave.')};card.onpointermove=move;card.onpointerup=finish;card.onpointercancel=finish}})}
