const renderCargoBeforeSlotTerminology=renderCargo;renderCargo=()=>{renderCargoBeforeSlotTerminology();$$('#manifest small,#cargoHold small').forEach(element=>{element.textContent=element.textContent.replace(/\bbloco\b/g,'slot').replace(/\bblocos\b/g,'slots')});const summary=$('#cargoSummary');if(summary)summary.innerHTML=summary.innerHTML.replace('Espaços ocupados','Slots ocupados')};
const SHIP_PROFILES={courier:{pt:'Veterana das rotas lunares, a Courier Mk I é simples, barata de manter e quase totalmente manual. Sua estrutura antiga e enferrujada atende serviços básicos, mas oferece pouca carga, autonomia limitada e menor tolerância a erros de pilotagem.',en:'A veteran of lunar routes, the Courier Mk I is simple, inexpensive to maintain, and almost entirely manual. Its old, rusted frame handles basic work but offers little cargo space, limited range, and less tolerance for piloting mistakes.'},hauler:{pt:'A Atlas Hauler é a primeira cargueira profissional da frota. Sua fuselagem utilitária branca combina tanque maior, estrutura reforçada e controles mais previsíveis para transportar cargas pesadas em rotas planetárias com segurança superior.',en:'The Atlas Hauler is the fleet’s first professional freighter. Its white utility hull combines a larger tank, reinforced structure, and more predictable controls to carry heavy cargo across planetary routes with greater safety.'},swift:{pt:'A Kestrel S2 troca o perfil industrial por desempenho esportivo. Motores responsivos, estabilidade aprimorada e ajustes de precisão favorecem entregas urgentes e cargas frágeis, reduzindo as correções necessárias em aproximações difíceis.',en:'The Kestrel S2 trades an industrial profile for sporting performance. Responsive engines, improved stability, and precision tuning favor urgent deliveries and fragile cargo while reducing corrections on difficult approaches.'},voyager:{pt:'A Aurora Voyager inaugura as operações de longa distância da transportadora. Seus oito slots, grande autonomia e sistemas avançados de controle sustentam viagens extragalácticas e operações de frota, superando amplamente qualquer nave planetária aprimorada.',en:'The Aurora Voyager opens long-range operations for the company. Its eight slots, extensive range, and advanced control systems support extragalactic travel and fleet operations, far surpassing any upgraded planetary ship.'},diplomat:{pt:'A Zenith Diplomat representa o ápice da engenharia comercial e diplomática. Com dez slots, autonomia extrema, estabilização de elite e sistemas redundantes, foi construída para as rotas mais remotas, valiosas e perigosas entre civilizações.',en:'The Zenith Diplomat represents the peak of commercial and diplomatic engineering. With ten slots, extreme range, elite stabilization, and redundant systems, it was built for the most remote, valuable, and dangerous routes between civilizations.'}};
function shipProfile(key){const profile=SHIP_PROFILES[key];return GAME_LANGUAGE==='en-US'?profile.en:profile.pt}
const renderGarageBeforeProfiles=renderGarage;renderGarage=()=>{renderGarageBeforeProfiles();$$('#shipShop .dealership-card').forEach(card=>{const key=Object.keys(SHIPS).find(shipKey=>SHIPS[shipKey].name===card.querySelector('h2')?.textContent),paragraph=card.querySelector('h2')?.parentElement?.querySelector('p');if(key&&paragraph)paragraph.textContent=shipProfile(key)});$$('#fleetGrid .fleet-card').forEach(card=>{const key=Object.keys(SHIPS).find(shipKey=>SHIPS[shipKey].name===card.querySelector('h2')?.textContent),details=card.querySelector('.fleet-details');if(!key||!details)return;details.querySelector('.ship-profile')?.remove();details.querySelector('.fleet-title')?.insertAdjacentHTML('afterend',`<p class="ship-profile">${shipProfile(key)}</p>`)})};
const DESTINATION_STORIES={
 Sol:{pt:`A Gaiola de Dyson Helios não é uma esfera contínua, mas um enxame de milhões de coletores solares, oficinas e habitats blindados em órbitas coordenadas ao redor do Sol. A energia capturada alimenta cidades e portais por todo o Sistema Solar, enquanto equipes de manutenção vivem sob turnos rigorosos, protegidas por escudos magnéticos e enormes painéis de sombra. Da doca, a fotosfera ocupa o horizonte inteiro: arcos de plasma maiores que planetas erguem-se sob uma luz branca e dourada que nenhuma janela comum suportaria.`,en:`The Helios Dyson Cage is not a solid sphere but a swarm of millions of solar collectors, workshops, and shielded habitats in coordinated orbits around the Sun. Its captured energy powers cities and gateways across the Solar System, while maintenance crews live under strict shifts behind magnetic shields and enormous sunshades. From the dock, the photosphere fills the entire horizon as plasma arcs larger than planets rise through white-gold light no ordinary window could withstand.`,humanPt:`Ejeções coronais podem interromper a refrigeração e transformar um habitat em uma fornalha em poucos minutos. Refrigerante, blindagem e módulos de sombra são transportados gratuitamente durante alertas solares, pois a evacuação entre órbitas é lenta e toda a rede energética depende da sobrevivência dessas equipes.`,humanEn:`Coronal ejections can disable cooling and turn a habitat into a furnace within minutes. Coolant, shielding, and sunshade modules travel free during solar alerts because evacuation between orbits is slow and the entire energy network depends on those crews surviving.`},
 Halley:{pt:`A Colônia Halley não ocupa uma órbita tranquila: ela viaja presa ao núcleo do cometa mais famoso da história humana. Túneis pressurizados, refinarias e alojamentos são escavados no gelo escuro, enquanto torres externas recolhem água, deutério e moléculas orgânicas reveladas pela sublimação. Quando Halley se aproxima do Sol, gêiseres despertam sem aviso e a cauda luminosa envolve a colônia; quando retorna à escuridão exterior, os mineiros passam anos sob um céu quase imóvel, mantendo uma economia construída para sobreviver ao isolamento.`,en:`Halley Colony does not occupy a quiet orbit: it travels attached to the nucleus of humanity's most famous comet. Pressurized tunnels, refineries, and living quarters are carved into dark ice, while outer towers collect water, deuterium, and organic molecules exposed by sublimation. As Halley approaches the Sun, geysers awaken without warning and the luminous tail surrounds the colony; when it returns to the outer darkness, miners spend years beneath an almost motionless sky, sustaining an economy built to survive isolation.`,humanPt:`Jatos repentinos podem romper cabos, soterrar acessos e deixar equipes presas em poços distantes. Oxigênio, aquecedores e novas âncoras viajam gratuitamente nesses acidentes, porque esperar pela próxima janela de aproximação condenaria os mineiros antes da chegada de outro cargueiro.`,humanEn:`Sudden jets can snap cables, bury access shafts, and strand teams in remote pits. Oxygen, heaters, and new anchors travel free during these accidents because waiting for the next approach window would doom the miners before another freighter could arrive.`},
 Lua:{pt:`As colônias do polo sul lunar nasceram ao redor das primeiras minas de gelo e hoje sustentam observatórios, hospitais e estaleiros que atendem toda a rota terrestre. Depois do colapso dos antigos consórcios, os habitantes passaram a recuperar máquinas abandonadas e dependem de entregas regulares para manter a produção de água, oxigênio e energia durante as longas noites lunares.`,en:`The lunar south-pole colonies grew around the first ice mines and now support observatories, hospitals, and shipyards serving the entire Earth route. After the old consortiums collapsed, residents began recovering abandoned machinery and now depend on regular deliveries to maintain water, oxygen, and power through the long lunar nights.`,humanPt:`A reserva comunitária abastece todos os habitats, inclusive os que não conseguem pagar fretes. Quando o estoque vital entra no limite, o Sindicato solicita espaço gratuito para água, oxigênio ou peças médicas, evitando que uma falha local coloque milhares de colonos em risco.`,humanEn:`The community reserve supplies every habitat, including those unable to pay freight. When vital stocks reach their limit, the Union requests free space for water, oxygen, or medical parts so a local failure does not endanger thousands of colonists.`},
 Marte:{pt:`Valles Marineris reúne cidades escavadas na rocha, fazendas pressurizadas e oficinas que mantêm os comboios de superfície em movimento. Tempestades de poeira podem interromper as rotas por semanas, desgastando filtros, painéis e sistemas de vedação; por isso, a economia marciana paga bem por pilotos capazes de entregar componentes antes do fechamento das janelas atmosféricas.`,en:`Valles Marineris contains cities carved into rock, pressurized farms, and workshops that keep surface convoys moving. Dust storms can cut routes for weeks and wear down filters, panels, and seals, so the Martian economy pays well for pilots who deliver components before atmospheric windows close.`,humanPt:`As colônias menores compartilham ar, medicamentos e alimentos durante tempestades prolongadas. As cargas humanitárias não geram frete porque abastecem abrigos coletivos e equipes de resgate, garantindo a sobrevivência até que as rotas terrestres sejam reabertas.`,humanEn:`Smaller colonies share air, medicine, and food during prolonged storms. Humanitarian cargo pays no freight because it supplies collective shelters and rescue crews until surface routes reopen.`},
 Europa:{pt:`Sob quilômetros de gelo, a expedição Nereida encontrou sinais químicos que podem transformar a compreensão da vida no Sistema Solar. Os laboratórios subglaciais operam em isolamento rigoroso, usando equipamentos esterilizados, baterias criogênicas e redes sísmicas; qualquer contaminação ou atraso pode encerrar anos de pesquisa e comprometer o delicado oceano de Europa.`,en:`Beneath kilometers of ice, the Nereid expedition found chemical signs that may transform humanity's understanding of life in the Solar System. Subglacial laboratories operate under strict isolation with sterile instruments, cryogenic batteries, and seismic networks; contamination or delay could end years of research and compromise Europa's delicate ocean.`,humanPt:`O calor dos habitats depende de uma rede única, sem alternativa de evacuação rápida. Aquecedores, selos e rações de emergência viajam gratuitamente quando uma estação perde energia, pois a demora significaria congelamento dos módulos e abandono permanente da base.`,humanEn:`Habitat heat depends on a single network with no rapid evacuation option. Heaters, seals, and emergency rations travel free when a station loses power because delay would freeze the modules and force permanent abandonment.`},
 Vênus:{pt:`As cidades aerostáticas de Vênus flutuam acima das nuvens corrosivas, sustentadas por enormes membranas e redes de gás constantemente reparadas. Aphrodite tornou-se um centro de pesquisa atmosférica e fabricação de polímeros, mas ventos violentos e ácido danificam estruturas externas; cada pouso exige precisão para não desestabilizar as plataformas habitadas.`,en:`Venus's aerostatic cities float above corrosive clouds, supported by enormous membranes and gas networks that require constant repair. Aphrodite became a center for atmospheric research and polymer production, but violent winds and acid damage external structures; every landing demands precision to avoid destabilizing inhabited platforms.`,humanPt:`Uma ruptura de flutuação ameaça bairros inteiros, não apenas um cliente. Filtros respiratórios, válvulas e remendos estruturais são transportados sem cobrança quando a altitude de uma cidade começa a cair, porque toda a população participa do esforço para impedir sua perda.`,humanEn:`A flotation rupture threatens entire districts, not one customer. Breathing filters, valves, and structural patches are carried without charge when a city's altitude begins to fall because the whole population joins the effort to prevent its loss.`},
 Titã:{pt:`A colônia Huygens cresceu ao redor dos lagos de metano, onde refinarias produzem combustível e materiais para as rotas exteriores. Durante o inverno, a luz diminui, rios congelam e torres meteorológicas orientam comboios entre assentamentos distantes; cargas térmicas e equipamentos criogênicos tornam-se valiosos e particularmente difíceis de transportar.`,en:`The Huygens colony grew around methane lakes where refineries produce fuel and materials for outer-system routes. During winter, light fades, rivers freeze, and weather towers guide convoys between distant settlements; thermal cargo and cryogenic equipment become valuable and especially difficult to transport.`,humanPt:`Quando as tempestades fecham os lagos, comunidades isoladas deixam de receber calor e comida. O frete humanitário leva rações térmicas, luzes de pista e geradores sem remuneração para manter os abrigos ativos até a chegada da estação segura.`,humanEn:`When storms close the lakes, isolated communities lose heat and food deliveries. Humanitarian freight carries thermal rations, runway lights, and generators without payment to keep shelters running until the safe season returns.`},
 Andrômeda:{pt:`A ponte de dobra para Andrômeda abriu o primeiro comércio permanente entre a humanidade e os arquipélagos orbitais de Asterion. As trocas combinam biotecnologia, memória cultural e fontes de energia sob um tratado ainda frágil, no qual cada carga também representa confiança diplomática; atrasos ou danos podem afetar relações construídas ao longo de gerações.`,en:`The warp bridge to Andromeda opened the first permanent trade between humanity and Asterion's orbital archipelagos. Exchanges combine biotechnology, cultural memory, and energy under a still-fragile treaty in which every shipment represents diplomatic trust; delays or damage can affect relationships built over generations.`,humanPt:`Organismos humanos e asterianos ainda não compartilham as mesmas defesas biológicas. Vacinas e estabilizadores ambientais seguem gratuitamente durante surtos, como compromisso mútuo do tratado: nenhuma civilização poderá lucrar com uma emergência sanitária da outra.`,humanEn:`Human and Asterion organisms still lack the same biological defenses. Vaccines and environmental stabilizers travel free during outbreaks under a treaty pledge that neither civilization may profit from the other's health emergency.`},
 Triângulo:{pt:`As cidades-jardim Lyri organizam o comércio como um ritual de equilíbrio entre utilidade, beleza e memória. Mercadorias são avaliadas não apenas pelo preço, mas pelo significado oferecido a cada comunidade; pilotos estrangeiros precisam respeitar protocolos de chegada, preservar cargas vivas e demonstrar que a humanidade é uma parceira confiável.`,en:`The Lyri garden cities treat commerce as a ritual balance of utility, beauty, and memory. Goods are judged not only by price but by the meaning offered to each community; foreign pilots must respect arrival protocols, preserve living cargo, and prove humanity can be trusted.`,humanPt:`A água das cidades-jardim circula por um ecossistema compartilhado. Quando uma reserva é contaminada, o envio gratuito de água selada e sementes impede fome coletiva; cobrar nessas ocasiões seria considerado pelos Lyri uma ruptura grave do pacto comercial.`,humanEn:`Water in the garden cities circulates through a shared ecosystem. When a reserve is contaminated, free sealed water and seeds prevent collective famine; charging in such moments would be considered a serious breach of the trade pact.`},
 Escultor:{pt:`Na galáxia anã do Escultor, os Veyr vivem em estações nômades que migram entre estrelas antigas para colher materiais raros. Seus comboios mudam de posição constantemente e utilizam tecnologias sensíveis a vibração, radiação e variações inerciais; alcançar o ponto de encontro já é parte do desafio, e somente as melhores naves suportam a viagem.`,en:`In the Sculptor Dwarf Galaxy, the Veyr live aboard nomadic stations migrating among ancient stars to harvest rare materials. Their convoys constantly change position and use technology sensitive to vibration, radiation, and inertial shifts; reaching the rendezvous is part of the challenge, and only the finest ships survive the journey.`,humanPt:`As estações Veyr não possuem planetas para onde evacuar. Células vitais e jardins encapsulados são levados sem cobrança quando um comboio perde suporte biológico, pois a falha de uma única estação pode apagar uma comunidade e todo o conhecimento que ela transporta.`,humanEn:`Veyr stations have no planets to evacuate to. Life cells and encapsulated gardens are carried without charge when a convoy loses biological support because one station's failure could erase a community and all the knowledge it carries.`}
};
let destinationLoreExpanded=false,destinationLoreSelected=null;const renderContractsBeforeDestinationLore=renderContracts;renderContracts=()=>{renderContractsBeforeDestinationLore();$$('#contractList .lore').forEach(element=>element.remove());const destination=acceptedCargo()[0]?.destination||(filter!=='Todos'?filter:null),panel=$('#destinationLore'),toggle=$('#toggleDestinationLore');if(!panel||!toggle)return;if(destination!==destinationLoreSelected){destinationLoreSelected=destination;destinationLoreExpanded=false}if(!destination||!DESTINATION_STORIES[destination]){destinationLoreExpanded=false;toggle.classList.add('hidden');panel.classList.add('hidden');panel.innerHTML='';return}const story=DESTINATION_STORIES[destination],english=GAME_LANGUAGE==='en-US',planet=DESTINATIONS[destination];toggle.classList.remove('hidden');toggle.textContent=destinationLoreExpanded?(english?'Hide destination story':'Ocultar história do destino'):`${english?'Read destination story':'Ler a história do destino'} · ${destination}`;toggle.onclick=()=>{destinationLoreExpanded=!destinationLoreExpanded;renderContracts()};if(!destinationLoreExpanded){panel.classList.add('hidden');panel.innerHTML='';return}panel.classList.remove('hidden');panel.style.setProperty('--planet-color',planet.color);panel.innerHTML=`<div class="destination-heading"><span class="destination-orb">●</span><div><small>${english?'COLONY DOSSIER':'ARQUIVO DA COLÔNIA'}</small><h2>${destination}</h2></div></div><p>${english?story.en:story.pt}</p><div class="humanitarian-note"><b>${english?'WHY HUMANITARIAN FREIGHT IS UNPAID':'POR QUE O FRETE HUMANITÁRIO É GRATUITO'}</b>${english?story.humanEn:story.humanPt}</div>`};
renderContracts();renderCargo();renderGarage();

if(GAME_EDITION!=='android'){const renderAFKBeforeMoodBar=renderAFK;renderAFK=()=>{renderAFKBeforeMoodBar();$$('.staff-card.employed').forEach(card=>{const name=card.querySelector('h2')?.textContent,e=state.afk.employees.find(x=>x.name===name),old=card.querySelector('.mood');if(!e||!old)return;old.outerHTML=`<div class="mood-meter" title="Humor: ${Math.round(e.mood)} de 100"><span>😢</span><div><i style="width:${Math.max(0,Math.min(100,e.mood))}%"></i></div><span>😊</span><b>${Math.round(e.mood)}%</b></div>`});$$('.trip-log').forEach((card,i)=>{const log=state.afk.log[i],economy=card.querySelector('.trip-economy');if(!log||!economy)return;const spans=[...economy.querySelectorAll('span')],freight=spans[0],fuel=spans.find(s=>s.textContent.startsWith('Combustível'));if(freight&&!economy.querySelector('.tax-line'))freight.insertAdjacentHTML('afterend',`<span class="tax-line">Imposto 27% −${(log.tax||0).toLocaleString('pt-BR')}</span>`);const taxLine=economy.querySelector('.tax-line');if(log.loanPayment&&taxLine&&!economy.querySelector('.loan-line'))taxLine.insertAdjacentHTML('afterend',`<span class="loan-line">Empréstimo −${log.loanPayment.toLocaleString('pt-BR')}</span>`);if(fuel)fuel.textContent=`Abastecimento automático −${log.fuelCost.toLocaleString('pt-BR')}`;const net=economy.querySelector('b');if(log.managerFee&&net)net.insertAdjacentHTML('beforebegin',`<span>Gerente −${log.managerFee.toLocaleString('pt-BR')}</span>`)})};renderAFK()}
const pResultBeforeBusinessCosts=pResult;pResult=(...args)=>{pResultBeforeBusinessCosts(...args);const d=state.afk?.lastManualDeductions;if(!d)return;const panel=$('#resultPanel'),actions=panel.querySelector('.result-actions'),old=panel.querySelector('.business-costs');if(old)old.remove();actions?.insertAdjacentHTML('beforebegin',`<p class="business-costs">Imposto sobre entregas · 27%: <b>−${(d.tax||0).toLocaleString('pt-BR')} CR</b><br>Receita após imposto: <b>${(d.afterTax||0).toLocaleString('pt-BR')} CR</b>${d.loanPayment?`<br>Pagamento do empréstimo · 10% do bruto: <b>−${d.loanPayment.toLocaleString('pt-BR')} CR</b>`:''}${d.managerFee?`<br>Comissão do gerente: <b>−${d.managerFee.toLocaleString('pt-BR')} CR</b>`:''}</p>`)};

// Crédito empresarial disponível desde o início da carreira.
takeLoan=amount=>{ensureAdvancedAFK();if(state.afk.loan)return toast(GAME_LANGUAGE==='en-US'?'Pay off the current loan before taking another.':'Quite o empréstimo atual antes de contratar outro.');amount=Number(amount);const interest=Math.round(amount*ECONOMY.loanInterest);state.credits+=amount;state.afk.loan={principal:amount,principalRemaining:amount,interestRemaining:interest,balance:amount+interest,termRate:ECONOMY.loanInterest,takenAt:Date.now()};save();updateHeader();renderCreditPanel();toast(`${GAME_LANGUAGE==='en-US'?'Business loan received':'Empréstimo contratado'}: ${amount.toLocaleString(GAME_LANGUAGE==='en-US'?'en-US':'pt-BR')} CR.`)};
function renderCreditPanel(){ensureAdvancedAFK();const a=state.afk,panel=$('#loanPanel');if(!panel)return;panel.innerHTML=a.loan?`<article class="manager-card"><h2>Empréstimo ativo</h2><p>Principal: <b>${a.loan.principal.toLocaleString('pt-BR')} CR</b></p><p>Saldo com juros de 5%: <b>${a.loan.balance.toLocaleString('pt-BR')} CR</b></p><p>Cobrança automática: <b>10% do valor bruto</b> de cada entrega, após o imposto e antes dos demais descontos.</p></article>`:`<article class="manager-card"><h2>Capital para sua transportadora</h2><p>Disponível desde o nível 1. Juros únicos de 5%; a amortização consome 10% do valor bruto de cada entrega, após o imposto e antes dos demais descontos.</p><div class="loan-buttons">${[10000,25000,50000,100000].map(v=>`<button class="secondary" data-loan="${v}">${v.toLocaleString('pt-BR')} CR</button>`).join('')}</div></article>`;$$('[data-loan]').forEach(button=>button.onclick=()=>takeLoan(button.dataset.loan))}
const renderAFKBeforeOpenCredit=renderAFK;renderAFK=()=>{renderAFKBeforeOpenCredit();renderCreditPanel()};
const creditNavButton=document.querySelector('[data-view="credit"]');if(creditNavButton)creditNavButton.onclick=()=>{nav('credit');renderCreditPanel()};
renderCreditPanel();
updateCreditNegativity();localStorage.setItem('cosmicCargoSave',JSON.stringify(state));checkCreditBankruptcy();setInterval(checkCreditBankruptcy,60000);

// Cada funcionário opera uma rota fixa; a carga de cada viagem é sorteada automaticamente.
const ensureAFKBeforeRoutes=ensureAFK;ensureAFK=()=>{ensureAFKBeforeRoutes();state.afk.employees.forEach(employee=>{if(typeof employee.routeDestination!=='string')employee.routeDestination=''})};
const staffStatusBeforeRoutes=staffStatus;staffStatus=(employee,now=Date.now())=>{const status=staffStatusBeforeRoutes(employee,now);if(status==='Disponível')return employee.routeDestination?`Disponível · rota ${employee.routeDestination}`:'Aguardando designação de destino';return status};
const employeeCanDispatchBeforeRoutes=employeeCanDispatch;employeeCanDispatch=(employee,now)=>!!employee.routeDestination&&employeeCanDispatchBeforeRoutes(employee,now);
chooseAFKContract=(employee,shipKey)=>{const ship=SHIPS[shipKey],destination=employee.routeDestination;if(!ship||!DESTINATIONS[destination]||isExtrasolarDestination(destination))return null;const available=contracts().filter(contract=>!contract.emergency&&contract.destination===destination&&contract.level<=employee.level&&contract.volume<=ship.slots&&contract.mass<=ship.mass);return available.length?available[Math.floor(Math.random()*available.length)]:null};
function assignEmployeeRoute(id,destination){ensureAFK();const employee=state.afk.employees.find(candidate=>candidate.id===id);if(!employee||employee.status==='traveling')return;if(destination&&(!DESTINATIONS[destination]||isExtrasolarDestination(destination)))return toast(GAME_LANGUAGE==='en-US'?'Employees can only operate Solar System routes.':'Funcionários operam somente rotas do Sistema Solar.');employee.routeDestination=destination;save();renderAFK();processAFK(true)}
function employeeRouteDurationLabel(employee,destination,english=false){const hours=(AUTO_ROUTE_HOURS[destination]||8)*staffStats(employee).speed,totalMinutes=Math.max(1,Math.round(hours*60)),wholeHours=Math.floor(totalMinutes/60),minutes=totalMinutes%60;return wholeHours?`${wholeHours}h${minutes?String(minutes).padStart(2,'0'):''}`:`${totalMinutes} min`}
const renderAFKBeforeRoutes=renderAFK;renderAFK=()=>{renderAFKBeforeRoutes();const english=GAME_LANGUAGE==='en-US',destinations=Object.keys(DESTINATIONS).filter(destination=>!isExtrasolarDestination(destination));$$('#crewGrid .staff-card.employed').forEach(card=>{const shipSelect=card.querySelector('[data-assign]'),controls=card.querySelector('.staff-controls');if(!shipSelect||!controls)return;const employee=state.afk.employees.find(candidate=>candidate.id===shipSelect.dataset.assign);if(!employee)return;const traveling=employee.status==='traveling',options=`<option value="">${english?'No destination':'Sem destino'}</option>`+destinations.map(destination=>`<option value="${destination}" ${employee.routeDestination===destination?'selected':''}>${destination} (${employeeRouteDurationLabel(employee,destination,english)})</option>`).join('');controls.insertAdjacentHTML('beforeend',`<label>${english?'Route destination':'Destino da rota'}<select data-assign-route="${employee.id}" ${traveling?'disabled':''}>${options}</select></label>`)});$$('[data-assign-route]').forEach(select=>select.onchange=()=>assignEmployeeRoute(select.dataset.assignRoute,select.value));$$('#shipShiftOrder .shift-order').forEach(card=>card.querySelectorAll('div').forEach(row=>{const name=row.querySelector('b')?.textContent?.replace(/^\d+\.\s*/,''),employee=state.afk.employees.find(candidate=>candidate.name===name),small=row.querySelector('small');if(employee&&small)small.textContent+=` · ${employee.routeDestination?`${employee.routeDestination} (${employeeRouteDurationLabel(employee,employee.routeDestination,english)})`:(english?'no route':'sem rota')}`}))};ensureAFK();renderAFK();

// Integra o reparo opcional pós-pouso ao resultado financeiro da missão.
function registerLandingRepair(cost){cost=Math.max(0,Math.round(cost||0));if(!cost)return;ensureFinance();const deductions=state.afk?.lastManualDeductions;if(deductions)deductions.repairPaid=(deductions.repairPaid||0)+cost;const entry=state.financeLedger.find(item=>item.kind==='manual'&&!item.landingRepairClosed);if(entry){entry.expenses=(entry.expenses||0)+cost;entry.net=(entry.net||0)-cost;entry.detail+=` · conserto ${financeMoney(cost)}`;entry.landingRepairClosed=true;if(deductions)deductions.netAfterRepair=entry.net}else{state.financeLedger.unshift({id:`fin-${Date.now()}-landing-repair`,time:Date.now(),kind:'repair',title:`Conserto pós-pouso · ${SHIPS[state.activeShip].name}`,detail:'Reparo realizado no fechamento da missão',gross:0,expenses:cost,tax:0,net:-cost});if(deductions)deductions.netAfterRepair=-cost}save();renderFinance()}
const pResultBeforeLandingRepairReceipt=pResult;pResult=(...args)=>{pResultBeforeLandingRepairReceipt(...args);const panel=$('#resultPanel'),deductions=state.afk?.lastManualDeductions,cost=deductions?.repairPaid||0;if(!panel||!cost)return;panel.querySelector('.landing-repair-receipt')?.remove();const english=GAME_LANGUAGE==='en-US',actions=panel.querySelector('.result-actions'),net=deductions.netAfterRepair;actions?.insertAdjacentHTML('beforebegin',`<p class="landing-repair-receipt">${english?'Repair performed after landing':'Conserto realizado após o pouso'}: <b>−${financeMoney(cost)}</b>${Number.isFinite(net)?`<br>${english?'Final mission result':'Resultado final da missão'}: <b class="${net>=0?'fuel-ok':'fuel-bad'}">${financeMoney(net)}</b>`:''}</p>`)};

// Histórias ampliadas com paisagens naturais e o entreposto de Plutão.
Object.assign(DESTINATION_STORIES.Lua,{pt:`As colônias do polo sul lunar nasceram ao redor das primeiras minas de gelo e hoje sustentam observatórios, hospitais e estaleiros. Das cúpulas, a Terra azul permanece suspensa sobre um horizonte cinzento, enquanto crateras de sombras eternas refletem o brilho baixo do Sol. Depois do colapso dos antigos consórcios, os habitantes passaram a recuperar máquinas abandonadas e dependem de entregas regulares para manter água, oxigênio e energia durante as longas noites lunares.`,en:`The lunar south-pole colonies grew around the first ice mines and now support observatories, hospitals, and shipyards. From their domes, blue Earth hangs above a gray horizon while permanently shadowed craters catch the Sun's low glow. After the old consortiums collapsed, residents began recovering abandoned machinery and now depend on regular deliveries for water, oxygen, and power through the long lunar nights.`});
Object.assign(DESTINATION_STORIES.Marte,{pt:`Valles Marineris reúne cidades escavadas na rocha, fazendas pressurizadas e oficinas que mantêm os comboios em movimento. Os cânions formam muralhas avermelhadas sob um céu cor de cobre, e o pôr do sol ganha um delicado halo azul ao redor do Sol. Tempestades de poeira podem interromper as rotas por semanas; por isso, a economia marciana paga bem por pilotos capazes de chegar antes do fechamento das janelas atmosféricas.`,en:`Valles Marineris contains cities carved into rock, pressurized farms, and workshops that keep surface convoys moving. The canyons rise as red walls beneath a copper sky, and sunset forms a delicate blue halo around the Sun. Dust storms can cut routes for weeks, so the Martian economy pays well for pilots who arrive before atmospheric windows close.`});
Object.assign(DESTINATION_STORIES.Europa,{pt:`Sob quilômetros de gelo, a expedição Nereida encontrou sinais químicos que podem transformar a compreensão da vida no Sistema Solar. Acima das planícies brancas, Júpiter domina quase todo o céu com suas faixas de nuvens e a Grande Mancha Vermelha; no solo, fraturas azuladas desenham o gelo como vidro. Os laboratórios subglaciais trabalham em isolamento rigoroso, pois qualquer contaminação ou atraso pode encerrar anos de pesquisa e comprometer o oceano de Europa.`,en:`Beneath kilometers of ice, the Nereid expedition found chemical signs that may transform humanity's understanding of life in the Solar System. Above the white plains, Jupiter dominates the sky with its cloud bands and Great Red Spot, while blue fractures draw glasslike patterns across the ice. Subglacial laboratories operate in strict isolation because contamination or delay could end years of research and compromise Europa's ocean.`});
Object.assign(DESTINATION_STORIES.Vênus,{pt:`As cidades aerostáticas de Vênus flutuam acima das nuvens corrosivas, sustentadas por enormes membranas e redes de gás. Do alto, o mar contínuo de nuvens douradas parece calmo e o nascer do Sol atravessa a névoa em tons de âmbar e violeta. Aphrodite tornou-se um centro de pesquisa atmosférica e fabricação de polímeros, mas ventos violentos e ácido castigam as estruturas externas; cada pouso exige precisão para não desestabilizar as plataformas.`,en:`Venus's aerostatic cities float above corrosive clouds, supported by enormous membranes and gas networks. From above, the endless golden cloud sea appears calm, and sunrise crosses the haze in amber and violet. Aphrodite became a center of atmospheric research and polymer production, but violent winds and acid punish external structures, making every landing a precision operation.`});
Object.assign(DESTINATION_STORIES.Titã,{pt:`A colônia Huygens cresceu ao redor dos lagos de metano, onde refinarias produzem combustível para as rotas exteriores. Dunas escuras, rios congelados e uma névoa alaranjada cercam os habitats; acima dela, Saturno ocupa o céu com seus anéis luminosos e sombras delicadas. Durante o inverno, a luz diminui e torres meteorológicas orientam comboios entre assentamentos distantes, tornando cargas térmicas e criogênicas especialmente valiosas.`,en:`The Huygens colony grew around methane lakes where refineries produce fuel for the outer routes. Dark dunes, frozen rivers, and orange haze surround the habitats; above it, Saturn fills the sky with luminous rings and delicate shadows. During winter the light fades, and weather towers guide convoys between distant settlements, making thermal and cryogenic cargo especially valuable.`});
DESTINATION_STORIES.Netuno={pt:`A cidade aerostática de Éolo deriva sobre a Grande Mancha Escura, presa a uma rede de balões, cabos e turbinas supersônicas. Em vez de resistir aos ventos mais velozes do Sistema Solar, seus engenheiros os canalizam para gerar energia e lançar cargueiros nas rotas exteriores com menor gasto de propulsão. Nuvens brancas de metano atravessam a atmosfera azul-profunda em poucos minutos, enquanto Tritão surge ao longe como uma lua clara sobre as tempestades.`,en:`The aerostatic city of Aeolus drifts above the Great Dark Spot, held by a network of balloons, cables, and supersonic turbines. Instead of resisting the fastest winds in the Solar System, its engineers channel them to generate power and launch freighters toward the outer routes with lower propulsion demand. White methane clouds race across the deep-blue atmosphere while Triton appears in the distance as a pale moon above the storms.`,humanPt:`Uma mudança repentina nas correntes pode arrancar plataformas de suas rotas seguras. Estabilizadores, rotores e balões de emergência viajam sem cobrança quando um habitat fica à deriva, pois poucas horas sem correção bastam para lançá-lo em camadas atmosféricas fatais.`,humanEn:`A sudden shift in the currents can tear platforms away from safe routes. Stabilizers, rotors, and emergency balloons travel free when a habitat begins to drift because only a few hours without correction can carry it into lethal atmospheric layers.`};
DESTINATION_STORIES.Plutão={pt:`O Porto Caronte foi construído na borda do Sistema Solar para preparar as naves que atravessarão a heliopausa. Estaleiros subterrâneos abastecem motores, bibliotecas de navegação e módulos de hibernação antes da partida definitiva. Ao redor da colônia, montanhas de gelo de água erguem-se sobre planícies de nitrogênio, o vasto coração claro de Tombaugh Planitia corta a superfície e Caronte paira enorme no céu escuro, formando uma paisagem silenciosa e inesquecível.`,en:`Charon Port was built at the edge of the Solar System to prepare ships that will cross the heliopause. Underground yards provision engines, navigation libraries, and hibernation modules before final departure. Around the colony, water-ice mountains rise above nitrogen plains, the bright heart of Tombaugh Planitia crosses the surface, and Charon hangs enormous in the dark sky, creating a silent and unforgettable landscape.`,humanPt:`As partidas dependem de janelas raras e não podem ser adiadas quando uma nave perde reservas vitais. O Sindicato transporta gratuitamente oxigênio, medicamentos, aquecedores e componentes de navegação para impedir que tripulações fiquem presas durante anos ou partam sem condições de sobrevivência.`,humanEn:`Departures depend on rare windows and cannot be delayed when a ship loses vital reserves. The Union carries oxygen, medicine, heaters, and navigation components free of charge so crews are not stranded for years or forced to depart without safe survival margins.`};
Object.assign(DESTINATION_STORIES.Andrômeda,{pt:`A ponte de dobra para Andrômeda abriu o primeiro comércio permanente com os arquipélagos orbitais de Asterion. Ilhas artificiais circulam estrelas azuladas entre auroras de plasma, jardins suspensos e nebulosas visíveis a olho nu. As trocas combinam biotecnologia, memória cultural e energia sob um tratado ainda frágil, no qual cada carga representa confiança diplomática.`,en:`The warp bridge to Andromeda opened the first permanent trade with Asterion's orbital archipelagos. Artificial islands orbit blue stars amid plasma auroras, suspended gardens, and nebulae visible to the naked eye. Exchanges combine biotechnology, cultural memory, and energy under a still-fragile treaty in which every shipment represents diplomatic trust.`});
Object.assign(DESTINATION_STORIES.Triângulo,{pt:`As cidades-jardim Lyri organizam o comércio como um ritual de equilíbrio entre utilidade, beleza e memória. Lagos espelhados, árvores bioluminescentes e pontes translúcidas refletem a luz de três sóis no horizonte, transformando cada chegada em uma cerimônia. Pilotos estrangeiros precisam respeitar protocolos, preservar cargas vivas e demonstrar que a humanidade é uma parceira confiável.`,en:`The Lyri garden cities treat commerce as a ritual balance of utility, beauty, and memory. Mirrored lakes, bioluminescent trees, and translucent bridges reflect three suns on the horizon, turning every arrival into a ceremony. Foreign pilots must respect protocols, preserve living cargo, and prove humanity can be trusted.`});
Object.assign(DESTINATION_STORIES.Escultor,{pt:`Na galáxia anã do Escultor, os Veyr vivem em estações nômades que migram entre estrelas antigas. Os comboios atravessam campos de luz tênue, aglomerados rubros e vazios tão transparentes que galáxias distantes parecem próximas. Suas tecnologias são sensíveis a vibração, radiação e variações inerciais; alcançar esse cenário remoto já é parte do desafio, e somente as melhores naves suportam a viagem.`,en:`In the Sculptor Dwarf Galaxy, the Veyr live aboard nomadic stations migrating among ancient stars. Their convoys cross fields of faint light, red clusters, and transparent voids where distant galaxies seem close. Their technology is sensitive to vibration, radiation, and inertial shifts; reaching this remote vista is part of the challenge, and only the finest ships survive the journey.`});

// Arquivos históricos e sociais mais profundos para cada destino.
const DEEPER_DESTINATION_LORE={
 Sol:{pt:`Helios começou como um conjunto de coletores experimentais e tornou-se a maior infraestrutura já construída pela humanidade. Cada segmento da Gaiola de Dyson segue sua própria órbita, trocando energia por feixes e ajustando continuamente sua posição para não colidir com os demais. Trabalhadores vivem em cidades estreitas no lado sombreado dos coletores e medem o tempo por ciclos artificiais, pois ali não existem dias ou noites. A proximidade da coroa oferece energia quase ilimitada, mas cobra vigilância constante: radiação, calor e tempestades magnéticas podem destruir comunicações antes que um alerta chegue à Terra. Pilotos aproximam-se por corredores protegidos, tendo diante deles um Sol tão vasto que parece não haver espaço escuro além da plataforma.`,en:`Helios began as a set of experimental collectors and became the largest infrastructure humanity has ever built. Each segment of the Dyson Cage follows its own orbit, exchanging power through beams and continuously adjusting position to avoid the others. Workers live in narrow cities on the collectors' shaded sides and measure time through artificial cycles because no day or night exists there. Proximity to the corona provides nearly limitless energy but demands constant vigilance: radiation, heat, and magnetic storms can destroy communications before an alert reaches Earth. Pilots approach through shielded corridors with a Sun so vast ahead of them that there seems to be no dark space beyond the platform.`},
 Halley:{pt:`A mineração de Halley começou com missões temporárias, mas a abundância de água pesada, carbono e compostos voláteis transformou os primeiros abrigos em uma colônia permanente. A comunidade move-se com o cometa durante toda a sua órbita de aproximadamente 76 anos e desenvolveu uma cultura própria: gerações inteiras nascem entre duas passagens pelo Sistema Solar interior. O núcleo irregular possui gravidade quase inexistente, obrigando edifícios, veículos e pessoas a permanecerem ancorados. Próximo ao Sol, fraturas liberam plumas que alteram a rotação e convertem o horizonte em uma tempestade brilhante de gelo e poeira; longe dele, a cauda desaparece e resta uma paisagem negra, azulada e silenciosa. Cada entrega precisa interceptar um alvo em movimento, tornando a Colônia Halley uma das rotas de mineração mais exigentes da transportadora.`,en:`Mining on Halley began with temporary expeditions, but abundant heavy water, carbon, and volatile compounds turned the first shelters into a permanent colony. The community travels with the comet throughout its roughly 76-year orbit and developed a culture of its own: entire generations are born between two passages through the inner Solar System. The irregular nucleus has almost no gravity, forcing buildings, vehicles, and people to remain anchored. Near the Sun, fractures release plumes that alter rotation and turn the horizon into a bright storm of ice and dust; far away, the tail vanishes, leaving a black, blue, and silent landscape. Every delivery must intercept a moving target, making Halley Colony one of the company's most demanding mining routes.`},
 Lua:{pt:`As colônias do polo sul lunar começaram como acampamentos provisórios de mineração, instalados junto às crateras onde o gelo permaneceu intocado por bilhões de anos. Quando os primeiros consórcios faliram, técnicos, cientistas e suas famílias decidiram ficar e transformaram equipamentos abandonados em uma sociedade cooperativa. Hoje, observatórios, hospitais e estaleiros vivem da água extraída das sombras eternas, mas cada litro de ar e cada peça mecânica ainda precisa ser contabilizado. Das cúpulas, a Terra azul permanece imóvel sobre o horizonte cinzento, lembrando aos moradores que seu antigo lar está perto o bastante para ser visto e distante demais para socorrê-los rapidamente.`,en:`The lunar south-pole colonies began as temporary mining camps beside craters where ice had remained untouched for billions of years. When the first corporations collapsed, technicians, scientists, and their families chose to stay, turning abandoned machinery into a cooperative society. Today, observatories, hospitals, and shipyards depend on water extracted from permanent shadow, yet every liter of air and every mechanical part must still be accounted for. From the domes, blue Earth hangs motionless above the gray horizon, reminding residents that their former home is close enough to see but too distant for immediate rescue.`},
 Marte:{pt:`Valles Marineris abriga uma cadeia de cidades escavadas nas paredes do cânion, unidas por comboios que atravessam milhares de quilômetros de deserto. As primeiras gerações chegaram para terraformar Marte; seus descendentes abandonaram a promessa de transformar todo o planeta e passaram a aperfeiçoar pequenos territórios habitáveis, protegidos por rocha e disciplina comunitária. Fazendas pressurizadas, fundições e oficinas sustentam uma cultura orgulhosa de sua autonomia, embora filtros, remédios e componentes delicados ainda venham da Terra. Sob o céu cor de cobre, o pôr do sol azul anuncia tanto a beleza do mundo quanto as tempestades capazes de isolar uma cidade por semanas.`,en:`Valles Marineris shelters a chain of cities carved into the canyon walls and linked by convoys crossing thousands of kilometers of desert. The first generations came to terraform Mars; their descendants abandoned the dream of changing the entire planet and instead perfected small habitable territories protected by rock and communal discipline. Pressurized farms, foundries, and workshops support a culture proud of its independence, although filters, medicine, and delicate components still arrive from Earth. Beneath the copper sky, the blue sunset signals both the world's beauty and the storms capable of isolating a city for weeks.`},
 Europa:{pt:`A colônia Nereida existe para responder a uma pergunta que dividiu a humanidade durante séculos: se a vida surgiu também sob o gelo de Europa. Laboratórios esterilizados descem por poços térmicos até o oceano subterrâneo, enquanto os alojamentos da superfície seguem protocolos rígidos para impedir que microrganismos terrestres contaminem a descoberta. Pesquisadores vivem por contratos longos, separados das famílias e cercados pelo som constante do gelo em movimento. Acima das planícies brancas e fraturadas, Júpiter domina o céu como uma parede de nuvens coloridas. Ali, uma caixa danificada pode representar não apenas prejuízo, mas a perda de uma amostra única ou de anos inteiros de trabalho científico.`,en:`The Nereid colony exists to answer a question that divided humanity for centuries: whether life also emerged beneath Europa's ice. Sterile laboratories descend through thermal shafts toward the buried ocean, while surface habitats follow strict protocols to prevent Earth organisms from contaminating the discovery. Researchers live under long contracts, separated from their families and surrounded by the constant sound of moving ice. Above the fractured white plains, Jupiter dominates the sky like a wall of colored clouds. There, a damaged container may mean not merely financial loss but the destruction of a unique sample or years of scientific work.`},
 Vênus:{pt:`Aphrodite não toca o solo de Vênus. A cidade flutua em uma faixa da atmosfera onde pressão e temperatura permitem a vida, sustentada por membranas cheias de gás e por milhares de correções automáticas de altitude. Seus habitantes aprenderam a medir o tempo pelo movimento das nuvens, e não pelo horizonte oculto sob o oceano corrosivo. A economia combina pesquisa climática, química industrial e fabricação de polímeros resistentes, mas sua prosperidade depende de manutenção permanente: um pequeno vazamento pode obrigar bairros inteiros a migrar entre plataformas. Ao amanhecer, a luz atravessa a névoa em tons dourados e violetas, criando uma beleza que contrasta com o mundo letal logo abaixo.`,en:`Aphrodite never touches the surface of Venus. The city floats within an atmospheric layer where pressure and temperature permit life, supported by gas-filled membranes and thousands of automatic altitude corrections. Its inhabitants learned to measure time by the movement of clouds rather than by a horizon hidden beneath the corrosive ocean. The economy combines climate research, industrial chemistry, and resilient polymer manufacturing, but its prosperity depends on constant maintenance: a small leak can force entire districts to migrate between platforms. At dawn, light crosses the haze in gold and violet, creating beauty in sharp contrast with the lethal world below.`},
 Titã:{pt:`Huygens nasceu como refinaria e tornou-se a principal comunidade das rotas exteriores. Famílias vivem em habitats enterrados junto aos lagos de metano, onde hidrocarbonetos são transformados em combustível, plásticos e reservas químicas para missões distantes. A atmosfera espessa permite que aeronaves planem com facilidade, mas esconde tempestades, rios sazonais e longos períodos de frio capazes de paralisar comboios. A população desenvolveu uma cultura de hospitalidade: viajantes sempre encontram abrigo, pois ninguém sobrevive sozinho tão longe do Sol. Sobre a névoa alaranjada, Saturno e seus anéis ocupam o céu, uma visão grandiosa que os moradores raramente conseguem observar da superfície.`,en:`Huygens began as a refinery and became the principal community of the outer routes. Families live in buried habitats beside methane lakes, where hydrocarbons are transformed into fuel, plastics, and chemical reserves for distant missions. The dense atmosphere allows aircraft to glide easily, yet conceals storms, seasonal rivers, and long freezes capable of stopping every convoy. The population developed a culture of hospitality: travelers are always offered shelter because nobody survives alone so far from the Sun. Above the orange haze, Saturn and its rings fill the sky, a magnificent sight residents can rarely see from the surface.`},
 Netuno:{pt:`Éolo é uma cidade aerostática construída para não vencer os ventos de Netuno, mas viajar com eles. Plataformas habitáveis, turbinas e balões formam um arquipélago móvel que percorre corredores atmosféricos calculados com meses de antecedência. A energia abundante das tempestades alimenta indústrias e catapultas de carga, transformando a colônia em escala estratégica para as rotas mais externas. Seus moradores consideram estabilidade uma ilusão: casas, escolas e oficinas mudam constantemente de posição, e mapas envelhecem em poucas horas. Nuvens brancas de metano atravessam o azul profundo enquanto Tritão surge ao longe; sob essa beleza, um erro de navegação pode lançar uma plataforma em camadas onde nenhuma estrutura humana resiste.`,en:`Aeolus is an aerostatic city built not to defeat Neptune's winds but to travel with them. Habitable platforms, turbines, and balloons form a moving archipelago that follows atmospheric corridors calculated months in advance. The storms' abundant energy powers industries and cargo launchers, turning the colony into a strategic stop for the outermost routes. Its residents consider stability an illusion: homes, schools, and workshops constantly change position, and maps become obsolete within hours. White methane clouds race across the deep blue while Triton appears in the distance; beneath that beauty, one navigation error can cast a platform into layers no human structure can survive.`},
 Plutão:{pt:`O Porto Caronte foi criado como último abrigo antes da saída do Sistema Solar. Seus estaleiros subterrâneos montam módulos de hibernação, arquivos culturais e motores destinados a viagens sem garantia de retorno. A população reúne engenheiros, famílias de tripulantes e pessoas que preferiram viver na fronteira em vez de embarcar; por isso, cada partida é ao mesmo tempo celebração e despedida. Montanhas de gelo cercam a planície clara de Tombaugh, enquanto Caronte permanece enorme e quase imóvel no céu devido à rotação compartilhada dos dois mundos. Com o Sol reduzido a uma estrela muito brilhante, atrasos logísticos podem custar anos até a próxima janela de lançamento.`,en:`Charon Port was created as the final refuge before leaving the Solar System. Its underground shipyards assemble hibernation modules, cultural archives, and engines intended for journeys with no guarantee of return. The population includes engineers, crew families, and people who chose life on the frontier instead of departure, making every launch both a celebration and a farewell. Ice mountains surround bright Tombaugh Planitia while Charon remains enormous and nearly motionless in the sky because the two worlds share a locked rotation. With the Sun reduced to a very bright star, logistical delays can cost years before the next launch window.`},
 Andrômeda:{pt:`A ponte de dobra de Asterion encerrou séculos de solidão cósmica ao estabelecer o primeiro comércio permanente entre a humanidade e outra civilização. Seus arquipélagos orbitais não são cidades convencionais, mas ecossistemas construídos em torno de estrelas azuladas, onde jardins suspensos preservam memórias biológicas de mundos perdidos. Os asterianos tratam objetos, sementes e registros como partes vivas de sua história; por isso, contratos comerciais também funcionam como compromissos diplomáticos. Humanos ainda discutem quem deve controlar a ponte, enquanto cada entrega bem-sucedida reduz a desconfiança entre os povos. Auroras de plasma e nebulosas visíveis a olho nu tornam o destino deslumbrante, mas nenhum piloto esquece que um acidente pode provocar uma crise interestelar.`,en:`The Asterion warp bridge ended centuries of cosmic solitude by establishing the first permanent trade between humanity and another civilization. Its orbital archipelagos are not conventional cities but ecosystems built around blue stars, where suspended gardens preserve biological memories of lost worlds. Asterions regard objects, seeds, and records as living parts of their history, so commercial contracts also serve as diplomatic commitments. Humans still debate who should control the bridge, while every successful delivery reduces distrust between the two peoples. Plasma auroras and naked-eye nebulae make the destination breathtaking, but no pilot forgets that an accident could trigger an interstellar crisis.`},
 Triângulo:{pt:`As cidades-jardim Lyri cresceram em torno de lagos artificiais que armazenam água, informação genética e memória coletiva. Para os Lyri, produzir algo útil sem torná-lo belo é sinal de descuido; mercados, pontes e portos são construídos como obras vivas que mudam com as estações. Seu comércio não mede apenas preço e prazo, mas também a intenção de quem entrega, razão pela qual pilotos estrangeiros participam de cerimônias antes de descarregar. Árvores bioluminescentes refletem nos lagos sob a luz de três sóis, formando uma paisagem serena que esconde regras sociais complexas. A humanidade vê enormes oportunidades comerciais, mas ainda aprende que eficiência, naquele mundo, nunca vale mais que equilíbrio.`,en:`The Lyri garden cities grew around artificial lakes that store water, genetic information, and collective memory. To the Lyri, making something useful without making it beautiful is a sign of neglect; markets, bridges, and ports are living works that change with the seasons. Their commerce measures not only price and schedule but also the deliverer's intent, which is why foreign pilots take part in ceremonies before unloading. Bioluminescent trees reflect upon lakes beneath three suns, creating a serene landscape that conceals complex social rules. Humanity sees enormous commercial opportunity there but is still learning that, in this world, efficiency is never worth more than balance.`},
 Escultor:{pt:`Os Veyr perderam seu planeta natal antes de dominarem as viagens interestelares. Desde então, suas estações nômades percorrem a galáxia anã do Escultor, recolhendo matéria rara e preservando fragmentos de uma cultura que não pode mais retornar ao lugar onde nasceu. Cada estação abriga uma linhagem, uma biblioteca e um jardim próprio; quando duas frotas se encontram, trocam recursos e histórias antes de seguirem caminhos diferentes. Seus instrumentos são extremamente sensíveis a vibração, radiação e variações inerciais, exigindo pilotos excepcionais. Entre estrelas antigas, aglomerados rubros e vastos espaços transparentes, uma entrega humana não representa apenas comércio, mas a promessa de que os Veyr não precisam continuar completamente sozinhos.`,en:`The Veyr lost their homeworld before mastering interstellar travel. Since then, their nomadic stations have crossed the Sculptor Dwarf Galaxy, gathering rare matter and preserving fragments of a culture that can no longer return to its birthplace. Every station carries its own lineage, library, and garden; when two fleets meet, they exchange resources and stories before following separate paths. Their instruments are exceptionally sensitive to vibration, radiation, and inertial shifts, demanding extraordinary pilots. Among ancient stars, red clusters, and vast transparent voids, a human delivery represents more than commerce: it is a promise that the Veyr need not remain entirely alone.`}
};
Object.entries(DEEPER_DESTINATION_LORE).forEach(([destination,lore])=>Object.assign(DESTINATION_STORIES[destination],lore));

const renderContractsBeforeRouteGroups=renderContracts;
renderContracts=()=>{renderContractsBeforeRouteGroups();const container=$('#destinationFilter');if(!container)return;const english=GAME_LANGUAGE==='en-US',locked=acceptedCargo()[0]?.destination,available=Object.keys(DESTINATIONS).filter(name=>GAME_EDITION!=='android'||!isExtrasolarDestination(name)),solar=available.filter(name=>!isExtrasolarDestination(name)),extra=available.filter(name=>isExtrasolarDestination(name)),button=name=>`<button class="${filter===name?'active':''}" data-dest="${name}">${name==='Todos'?(english?'All':'Todos'):name}</button>`,group=(label,names,type)=>names.length?`<section class="destination-group ${type}"><span class="destination-group-label">${label}</span><div>${names.map(button).join('')}</div></section>`:'';if(locked){const extraSolar=isExtrasolarDestination(locked);container.innerHTML=group(extraSolar?(english?'EXTRASOLAR ROUTES':'ROTAS EXTRASSOLARES'):(english?'SOLAR SYSTEM':'SISTEMA SOLAR'),[locked],extraSolar?'extrasolar':'solar')}else container.innerHTML=`<div class="destination-all">${button('Todos')}</div>${group(english?'SOLAR SYSTEM':'SISTEMA SOLAR',solar,'solar')}${group(english?'EXTRASOLAR ROUTES':'ROTAS EXTRASSOLARES',extra,'extrasolar')}`;$$('#destinationFilter [data-dest]').forEach(buttonElement=>buttonElement.onclick=()=>{filter=buttonElement.dataset.dest;renderContracts()});const cards=$$('#contractList .card');cards.forEach(card=>{const name=card.querySelector('.route h2')?.textContent,extraSolar=isExtrasolarDestination(name);card.classList.add(extraSolar?'route-extrasolar':'route-solar')});if(!locked&&filter==='Todos'){const firstExtra=cards.find(card=>card.classList.contains('route-extrasolar')),firstSolar=cards.find(card=>card.classList.contains('route-solar'));firstSolar?.insertAdjacentHTML('beforebegin',`<div class="contract-route-divider solar">${english?'SOLAR SYSTEM CONTRACTS':'CONTRATOS DO SISTEMA SOLAR'}</div>`);firstExtra?.insertAdjacentHTML('beforebegin',`<div class="contract-route-divider extrasolar">${english?'EXTRASOLAR CONTRACTS':'CONTRATOS EXTRASSOLARES'}</div>`)}};
renderContracts();

// Cenários procedurais coerentes com a localização e a história de cada destino.
function drawWorld(ctx,x,y,r,colors){const gradient=ctx.createRadialGradient(x-r*.32,y-r*.36,r*.08,x,y,r);gradient.addColorStop(0,colors[0]);gradient.addColorStop(.62,colors[1]);gradient.addColorStop(1,colors[2]);ctx.fillStyle=gradient;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function drawDestinationBackdrop(name,w,h){ctx.save();ctx.globalAlpha=.9;if(name==='Lua'){drawWorld(ctx,w*.79,155,92,['#dff5ff','#328bd1','#082e67']);ctx.fillStyle='#63ae70aa';ctx.beginPath();ctx.ellipse(w*.76,137,28,13,-.35,0,Math.PI*2);ctx.ellipse(w*.82,171,21,10,.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffff99';ctx.lineWidth=3;ctx.beginPath();ctx.arc(w*.79,151,72,.15,2.6);ctx.stroke()}else if(name==='Europa'){const x=w*.79,y=166,r=132;drawWorld(ctx,x,y,r,['#fff2c9','#d29a67','#7d513e']);ctx.save();ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.clip();for(let i=-4;i<=4;i++){ctx.fillStyle=i%2?'#8d594e88':'#f0d1a688';ctx.fillRect(x-r,y+i*27,r*2,12)}ctx.fillStyle='#a84e3f';ctx.beginPath();ctx.ellipse(x+48,y+40,30,13,-.15,0,Math.PI*2);ctx.fill();ctx.restore()}else if(name==='Titã'){const x=w*.76,y=170,r=86;ctx.strokeStyle='#d8bd83aa';ctx.lineWidth=22;ctx.beginPath();ctx.ellipse(x,y+5,160,42,-.18,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#fff0b477';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(x,y+5,175,48,-.18,0,Math.PI*2);ctx.stroke();drawWorld(ctx,x,y,r,['#fff0bd','#d4a85f','#7e623c']);ctx.strokeStyle='#8c714f99';ctx.lineWidth=9;ctx.beginPath();ctx.ellipse(x,y+5,160,42,-.18,Math.PI*.05,Math.PI*.94);ctx.stroke()}else if(name==='Marte'){const sun=ctx.createRadialGradient(145,145,2,145,145,48);sun.addColorStop(0,'#d9ecff');sun.addColorStop(.35,'#83b9ff99');sun.addColorStop(1,'#83b9ff00');ctx.fillStyle=sun;ctx.beginPath();ctx.arc(145,145,48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7f2f2455';ctx.beginPath();ctx.moveTo(0,430);ctx.lineTo(95,300);ctx.lineTo(180,395);ctx.lineTo(295,275);ctx.lineTo(390,420);ctx.lineTo(520,330);ctx.lineTo(650,420);ctx.lineTo(760,290);ctx.lineTo(w,415);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill()}else if(name==='Vênus'){for(let i=0;i<9;i++){ctx.fillStyle=i%2?'#f7ca7760':'#fff0bd42';ctx.beginPath();ctx.ellipse((i*137+70)%w,120+(i%4)*72,150,35,.08,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#372b39bb';ctx.fillRect(w*.7,245,7,135);ctx.beginPath();ctx.ellipse(w*.7+3,241,64,16,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f5d99188';ctx.lineWidth=2;ctx.beginPath();ctx.arc(w*.7+3,242,43,Math.PI,0);ctx.stroke()}else if(name==='Netuno'){drawWorld(ctx,w*.8,156,46,['#edf6ff','#9bbbe0','#4b6688']);for(let i=0;i<7;i++){ctx.strokeStyle=i%2?'#b8e6ff55':'#4c8fff55';ctx.lineWidth=10+i%3*4;ctx.beginPath();ctx.moveTo(-40,95+i*43);ctx.bezierCurveTo(210,55+i*52,470,155+i*30,w+40,90+i*46);ctx.stroke()}ctx.fillStyle='#071c5c99';ctx.beginPath();ctx.ellipse(w*.68,260,92,38,-.18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#142c4ddd';ctx.fillRect(w*.43,245,8,120);ctx.beginPath();ctx.ellipse(w*.43+4,241,74,15,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8ce8ffcc';ctx.lineWidth=3;for(let side of [-1,1]){ctx.beginPath();ctx.arc(w*.43+side*42,241,19,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(w*.43+side*42,222);ctx.lineTo(w*.43+side*42,260);ctx.moveTo(w*.43+side*23,241);ctx.lineTo(w*.43+side*61,241);ctx.stroke()}}else if(name==='Plutão'){drawWorld(ctx,w*.79,145,55,['#e8e1da','#97877e','#433b3e']);ctx.fillStyle='#c8dce455';ctx.beginPath();ctx.moveTo(0,474);ctx.lineTo(105,340);ctx.lineTo(190,450);ctx.lineTo(300,310);ctx.lineTo(405,455);ctx.lineTo(535,360);ctx.lineTo(650,468);ctx.lineTo(770,325);ctx.lineTo(w,465);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.strokeStyle='#dff7ff88';ctx.lineWidth=2;ctx.stroke()}else if(name==='Andrômeda'){ctx.strokeStyle='#aa8cff44';for(let i=0;i<7;i++){ctx.lineWidth=18-i*2;ctx.beginPath();ctx.ellipse(w*.72,205,185-i*19,62-i*5,-.35,i*.38,Math.PI*1.45+i*.3);ctx.stroke()}ctx.fillStyle='#d9c8ff';ctx.beginPath();ctx.arc(w*.72,205,13,0,Math.PI*2);ctx.fill()}else if(name==='Triângulo'){[['#fff1a8',120,120,34],['#8eeaff',250,175,25],['#e5a6ff',385,110,20]].forEach(([color,x,y,r])=>{ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=35;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()});ctx.shadowBlur=0;ctx.strokeStyle='#61f0d255';ctx.lineWidth=4;for(let i=0;i<7;i++){const x=500+i*65;ctx.beginPath();ctx.moveTo(x,450);ctx.quadraticCurveTo(x-28,340,x+8,270-(i%3)*28);ctx.stroke()}}else if(name==='Escultor'){const gradient=ctx.createRadialGradient(w*.68,210,8,w*.68,210,220);gradient.addColorStop(0,'#ff74b855');gradient.addColorStop(.45,'#703e8d38');gradient.addColorStop(1,'#05081500');ctx.fillStyle=gradient;ctx.fillRect(350,0,610,470);ctx.strokeStyle='#ffb7dd88';ctx.lineWidth=3;for(let i=0;i<5;i++){const x=540+i*72,y=250+(i%2)*35;ctx.strokeRect(x,y,45,13);ctx.beginPath();ctx.moveTo(x-25,y+6);ctx.lineTo(x,y+6);ctx.stroke()}}ctx.restore()}

const drawDestinationBackdropBeforeSun=drawDestinationBackdrop;
drawDestinationBackdrop=(name,w,h)=>{if(name!=='Sol')return drawDestinationBackdropBeforeSun(name,w,h);ctx.save();ctx.globalAlpha=.95;const sun=ctx.createRadialGradient(w*.72,170,18,w*.72,170,270);sun.addColorStop(0,'#fffbd1');sun.addColorStop(.28,'#ffd34e');sun.addColorStop(.68,'#f47b20');sun.addColorStop(1,'#9b260000');ctx.fillStyle=sun;ctx.fillRect(230,-100,w-180,540);ctx.strokeStyle='#ffe59a88';ctx.lineWidth=4;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(w*.72,170,150+i*28,45+i*15,-.22,0,Math.PI*2);ctx.stroke()}ctx.strokeStyle='#7edfff99';ctx.lineWidth=3;for(let i=0;i<7;i++){const x=390+i*76,y=260+(i%2)*34;ctx.strokeRect(x,y,52,16);ctx.beginPath();ctx.moveTo(x+26,y+16);ctx.lineTo(x+26,380);ctx.stroke()}ctx.restore()};

const drawDestinationBackdropBeforeHalley=drawDestinationBackdrop;
drawDestinationBackdrop=(name,w,h)=>{if(name!=='Halley')return drawDestinationBackdropBeforeHalley(name,w,h);ctx.save();ctx.globalAlpha=.95;const nucleus=ctx.createRadialGradient(w*.74,185,12,w*.74,185,118);nucleus.addColorStop(0,'#bed9d5');nucleus.addColorStop(.38,'#667b7c');nucleus.addColorStop(1,'#18262d');ctx.fillStyle=nucleus;ctx.beginPath();ctx.moveTo(w*.62,135);ctx.quadraticCurveTo(w*.69,70,w*.8,105);ctx.quadraticCurveTo(w*.89,155,w*.83,245);ctx.quadraticCurveTo(w*.73,292,w*.63,225);ctx.quadraticCurveTo(w*.57,183,w*.62,135);ctx.fill();const tail=ctx.createLinearGradient(w*.62,170,0,310);tail.addColorStop(0,'#d8ffffaa');tail.addColorStop(.4,'#79d9e766');tail.addColorStop(1,'#3bbfd000');ctx.fillStyle=tail;ctx.beginPath();ctx.moveTo(w*.65,140);ctx.quadraticCurveTo(w*.38,185,0,245);ctx.lineTo(0,390);ctx.quadraticCurveTo(w*.4,270,w*.68,225);ctx.closePath();ctx.fill();ctx.strokeStyle='#a8f3f0aa';ctx.lineWidth=2;for(let i=0;i<6;i++){const x=w*.66+i*22,y=190+(i%2)*20;ctx.strokeRect(x,y,26,10);ctx.beginPath();ctx.moveTo(x+13,y+10);ctx.lineTo(x+13,355);ctx.stroke()}ctx.restore()};

// Livro-caixa permanente da transportadora.
function ensureFinance(){if(!Array.isArray(state.financeLedger))state.financeLedger=[];if(!state.financeMigrated){const oldLogs=state.afk?.log||[];oldLogs.slice().reverse().forEach(log=>state.financeLedger.unshift({id:`afk-${log.id}`,sourceId:log.id,time:log.endedAt||Date.now(),kind:'automatic',title:`${log.destination} · ${log.cargo}`,detail:`${log.employee} · ${log.ship}`,gross:log.gross||0,expenses:(log.tax||0)+(log.loanPayment||0)+(log.commission||0)+(log.benefits||0)+(log.fuelCost||0)+(log.repair||0)+(log.managerFee||0),tax:log.tax||0,net:log.net||0}));state.financeMigrated=true}state.financeLedger=state.financeLedger.slice(0,10)}
function addFinance(entry){ensureFinance();state.financeLedger.unshift({id:`fin-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,time:Date.now(),gross:0,expenses:0,tax:0,net:0,...entry});state.financeLedger=state.financeLedger.slice(0,10);save();renderFinance()}
function financeMoney(value){return`${Math.round(value||0).toLocaleString('pt-BR')} CR`}
function renderFinance(){ensureFinance();const summary=$('#financeSummary'),ledger=$('#financeLedger');if(!summary||!ledger)return;const english=GAME_LANGUAGE==='en-US',entries=state.financeLedger,totalGross=entries.reduce((n,e)=>n+(e.gross||0),0),totalExpenses=entries.reduce((n,e)=>n+(e.expenses||0),0),totalTax=entries.reduce((n,e)=>n+(e.tax||0),0),totalNet=entries.reduce((n,e)=>n+(e.net||0),0),taxDebt=state.taxEvasion?.debt||0;summary.innerHTML=`<article class="finance-kpi income"><small>${english?'GROSS REVENUE':'RECEITA BRUTA'}</small><b>${financeMoney(totalGross)}</b></article><article class="finance-kpi expense"><small>${english?'TOTAL EXPENSES':'DESPESAS TOTAIS'}</small><b>−${financeMoney(totalExpenses)}</b></article><article class="finance-kpi tax"><small>${english?'TAXES PAID / OUTSTANDING':'IMPOSTOS PAGOS / PENDENTES'}</small><b>${financeMoney(totalTax)} / ${financeMoney(taxDebt)}</b></article><article class="finance-kpi"><small>${english?'ACCUMULATED NET RESULT':'RESULTADO LÍQUIDO ACUMULADO'}</small><b class="finance-net ${totalNet>=0?'positive':'negative'}">${totalNet>=0?'+':'−'}${financeMoney(Math.abs(totalNet))}</b></article>`;if(!entries.length){ledger.innerHTML=`<div class="finance-empty">${english?'Financial activity from new contracts will appear here.':'As movimentações financeiras dos novos contratos aparecerão aqui.'}</div>`;return}const kindLabels={manual:english?'PILOTED CONTRACT':'CONTRATO PILOTADO',automatic:english?'AUTOMATIC CONTRACT':'CONTRATO AUTOMÁTICO',fuel:english?'REFUELING':'ABASTECIMENTO',repair:english?'REPAIR':'CONSERTO',tax_audit:english?'TAX AUDIT':'FISCALIZAÇÃO',tax_late:english?'OVERDUE TAX':'IMPOSTO ATRASADO',upgrade:english?'WORKSHOP UPGRADE':'MELHORIA DA OFICINA',ship_purchase:english?'SHIP PURCHASE':'COMPRA DE NAVE',ship_sale:english?'SHIP SALE':'VENDA DE NAVE',ship_recycling:english?'SHIP RECYCLING':'RECICLAGEM DE NAVE',loan_early_payment:english?'LOAN PAYMENT':'PAGAMENTO DE EMPRÉSTIMO',manager_training:english?'MANAGER TRAINING':'TREINAMENTO DE GERENTE',manager_severance:english?'MANAGER SEVERANCE':'RESCISÃO DE GERENTE',manager_hiring:english?'MANAGER HIRING':'CONTRATAÇÃO DE GERENTE',manager_leave:english?'MANAGER LEAVE':'AFASTAMENTO DE GERENTE',staff_hiring:english?'EMPLOYEE HIRING':'CONTRATAÇÃO DE FUNCIONÁRIO',staff_training:english?'EMPLOYEE TRAINING':'TREINAMENTO DE FUNCIONÁRIO',staff_severance:english?'EMPLOYEE SEVERANCE':'RESCISÃO DE FUNCIONÁRIO',staff_payroll:english?'WEEKLY PAYROLL':'FOLHA SEMANAL',staff_leave:english?'EMPLOYEE LEAVE':'AFASTAMENTO DE FUNCIONÁRIO',family_expenses:english?'FAMILY HEALTH AND EDUCATION':'SAÚDE E EDUCAÇÃO FAMILIAR',business_overhead:english?'CARRIER FIXED COSTS':'CUSTOS FIXOS DA TRANSPORTADORA',hangar_purchase:english?'HANGAR PROPERTY PURCHASE':'COMPRA DE IMÓVEL — HANGAR',loan:english?'BUSINESS LOAN':'CRÉDITO EMPRESARIAL'};ledger.innerHTML=entries.map(entry=>{const category=kindLabels[entry.kind]||(english?'OTHER TRANSACTION':'OUTRA MOVIMENTAÇÃO'),title=entry.title||(english?'Financial transaction':'Movimentação financeira'),detail=entry.detail||(english?'No additional description.':'Sem descrição adicional.'),time=Number(entry.time)||Date.now(),gross=Number(entry.gross)||0,expenses=Number(entry.expenses)||0,net=Number(entry.net)||0;return`<article class="finance-row"><div><span class="finance-kind">${category}</span><small>${new Date(time).toLocaleString(english?'en-US':'pt-BR')}</small></div><div><strong>${title}</strong><small>${detail}</small></div><span><small>${english?'Revenue':'Receita'}</small><strong>${gross?'+':''}${financeMoney(gross)}</strong></span><span><small>${english?'Expenses':'Despesas'}</small><strong>${expenses?'−':''}${financeMoney(expenses)}</strong></span><span><small>${english?'Result':'Resultado'}</small><strong class="finance-net ${net>=0?'positive':'negative'}">${net>=0?'+':'−'}${financeMoney(Math.abs(net))}</strong></span></article>`}).join('')}
ensureFinance();const financeButton=document.querySelector('[data-view="finance"]');if(financeButton)financeButton.onclick=()=>{nav('finance');renderFinance()};
const settleManualTaxBeforeFinance=settleManualTax;settleManualTax=evade=>{const pending=pendingTaxUI?{...pendingTaxUI}:null,destination=flight?.destination||state.lastDestination,before=state.credits;settleManualTaxBeforeFinance(evade);if(!pending)return;const deductions=state.afk?.lastManualDeductions||{},taxPaid=deductions.tax||0,loan=deductions.loanPayment||0,manager=deductions.managerFee||0,penalty=pending.cargoPenalty||0,expenses=taxPaid+loan+manager+penalty;addFinance({kind:'manual',title:`${destination||'Destino'} · ${pending.rows.length} contrato${pending.rows.length===1?'':'s'}`,detail:evade?`Imposto sonegado: ${financeMoney(deductions.assessedTax||0)} · dano ${pending.missionDamage}%`:`Imposto pago · dano ${pending.missionDamage}%`,gross:pending.originalTotal??pending.total,expenses,tax:taxPaid,managerFee:manager,net:state.credits-before})};
const payTaxAuditBeforeFinance=payTaxAudit;payTaxAudit=()=>{const before=state.credits,amount=state.taxEvasion?.audit?.amount||0;payTaxAuditBeforeFinance();if(amount)addFinance({kind:'tax_audit',title:'Multa da Receita Interplanetária',detail:'Impostos acumulados multiplicados por 2',expenses:amount,tax:amount,net:state.credits-before})};
const buyFuelBeforeFinance=buyFuel;buyFuel=amount=>{const before=state.credits,fuelBefore=state.fuel;buyFuelBeforeFinance(amount);const spent=before-state.credits,units=state.fuel-fuelBefore;if(spent>0)addFinance({kind:'fuel',title:`Abastecimento · ${SHIPS[state.activeShip].name}`,detail:`${Math.round(units)} unidades de combustível`,expenses:spent,net:-spent})};
const repairShipBeforeFinance=repairShip;repairShip=()=>{const before=state.credits,conditionBefore=state.condition,shipName=SHIPS[state.activeShip].name;repairShipBeforeFinance();const spent=before-state.credits;if(state.condition>conditionBefore)addFinance({kind:'repair',title:`Conserto · ${shipName}`,detail:`Integridade ${Math.round(conditionBefore)}% → 100%`,expenses:spent,net:-spent})};
const buyUpgradeBeforeFinance=buyUpgrade;buyUpgrade=key=>{const before=state.credits,levelBefore=state.upgrades[key]||0,shipName=SHIPS[state.activeShip].name,upgradeName=UPGRADES[key]?.name||key,baseCost=upgradeCost(key),tax=upgradePurchaseTax(key);buyUpgradeBeforeFinance(key);const spent=before-state.credits,levelAfter=state.upgrades[key]||0;if(spent>0&&levelAfter>levelBefore)addFinance({kind:'upgrade',title:upgradeName+' · '+shipName,detail:'Nível '+levelBefore+' → '+levelAfter+' · preço '+financeMoney(baseCost)+' · imposto de '+economyPercent(ECONOMY.upgradeTax)+' '+financeMoney(tax)+' · total '+financeMoney(spent),expenses:spent,tax,net:-spent})};
const renderGarageBeforeUpgradeTax=renderGarage;renderGarage=()=>{renderGarageBeforeUpgradeTax();$$('#upgradeShop [data-upgrade]').forEach(button=>{const key=button.dataset.upgrade,level=state.upgrades[key]||0;if(level>=UPGRADES[key].max)return;const base=upgradeCost(key),tax=upgradePurchaseTax(key),total=base+tax;button.innerHTML=`Comprar por ${total.toLocaleString('pt-BR')} CR<small>Preço ${base.toLocaleString('pt-BR')} + imposto ${economyPercent(ECONOMY.upgradeTax)} ${tax.toLocaleString('pt-BR')} CR</small>`;button.classList.toggle('unaffordable',total>state.credits)});};renderGarage();
function sellShip(key){const ship=SHIPS[key],english=GAME_LANGUAGE==='en-US';if(!ship||!state.ownedShips.includes(key))return;if(state.ownedShips.length<=1)return toast(english?'You must keep at least one ship.':'Você precisa manter pelo menos uma nave.');if(state.accepted.length)return toast(english?'Finish or cancel active contracts before selling a ship.':'Finalize ou cancele os contratos ativos antes de vender uma nave.');if(state.afk?.employees?.some(employee=>employee.shipKey===key))return toast(english?'Remove the employees assigned to this ship before selling it.':'Retire os funcionários designados para esta nave antes de vendê-la.');if(state.afk?.journeys?.some(journey=>journey.shipKey===key))return toast(english?'This ship is currently on an automatic journey.':'Esta nave está em uma viagem automática.');syncActiveShipData();const condition=key===state.activeShip?state.condition:(state.shipData[key]?.condition??100),value=shipTradeValueFor(key),message=english?`Sell ${ship.name} for ${value.toLocaleString('en-US')} CR? Fuel and upgrades will be lost.`:`Vender ${ship.name} por ${value.toLocaleString('pt-BR')} CR? O combustível e as melhorias serão perdidos.`;if(!confirm(message))return;const wasActive=key===state.activeShip;state.credits+=value;state.ownedShips=state.ownedShips.filter(shipKey=>shipKey!==key);state.tradedShips=[...new Set([...(state.tradedShips||[]),key])];delete state.shipData[key];if(wasActive){const replacement=[...state.ownedShips].sort((a,b)=>SHIPS[b].tier-SHIPS[a].tier)[0],data=normalizeShipRecord(state.shipData[replacement],replacement);state.activeShip=replacement;state.condition=data.condition;state.fuel=data.fuel;state.upgrades={...data.upgrades};state.slots=Array(SHIPS[replacement].slots).fill(null);state.cargoRotations={};state.stagedCargo=[];state.selectedSlot=0}save();addFinance({kind:'ship_sale',title:english?`Sale of ${ship.name}`:`Venda da ${ship.name}`,detail:english?`Trade-in appraisal at ${Math.round(condition)}% integrity.`:`Avaliação de troca com ${Math.round(condition)}% de integridade.`,gross:value,expenses:0,net:value});renderGarage();renderContracts();renderCargo();toast(english?`${ship.name} sold for ${value.toLocaleString('en-US')} CR.`:`${ship.name} vendida por ${value.toLocaleString('pt-BR')} CR.`)}
const renderGarageBeforeShipSale=renderGarage;renderGarage=()=>{renderGarageBeforeShipSale();const english=GAME_LANGUAGE==='en-US';$$('#fleetGrid .fleet-card').forEach(card=>{const key=Object.keys(SHIPS).find(shipKey=>SHIPS[shipKey].name===card.querySelector('h2')?.textContent),details=card.querySelector('.fleet-details');if(!key||!details)return;const assigned=state.afk?.employees?.some(employee=>employee.shipKey===key),traveling=state.afk?.journeys?.some(journey=>journey.shipKey===key),blocked=state.ownedShips.length<=1||state.accepted.length>0||assigned||traveling,value=shipTradeValueFor(key),reason=state.ownedShips.length<=1?(english?'Only ship':'Única nave'):state.accepted.length?(english?'Active contract':'Contrato ativo'):traveling?(english?'On a journey':'Em viagem'):assigned?(english?'Employee assigned':'Funcionário designado'):'';details.insertAdjacentHTML('beforeend',`<button class="danger ship-sale-button" data-sell-ship="${key}" ${blocked?'disabled':''}>${blocked?reason:(english?`Sell ship · ${value.toLocaleString('en-US')} CR`:`Vender nave · ${value.toLocaleString('pt-BR')} CR`)}</button>`)});$$('[data-sell-ship]').forEach(button=>button.onclick=()=>sellShip(button.dataset.sellShip))};renderGarage();

// Carrinho da Oficina: as melhorias só são aplicadas quando a compra é fechada.
let pendingUpgrades={shipKey:null,items:[]};
function upgradeCostAt(key,currentLevel){const upgrade=UPGRADES[key],ship=SHIPS[state.activeShip],level=currentLevel+1;if(level<=3)return Math.round(upgrade.base*ship.upgradeScale*[1,1.4,1.85][level-1]);const nextShip=Object.values(SHIPS).find(candidate=>candidate.tier===ship.tier+1);if(nextShip)return Math.round(upgrade.base*nextShip.upgradeScale*1.08);return Math.round(upgrade.base*ship.upgradeScale*([2.7,3.5,4.5][Math.min(6,level)-4]||4.5))}
function pendingUpgradeTotals(){const base=pendingUpgrades.items.reduce((sum,item)=>sum+item.base,0),tax=pendingUpgrades.items.reduce((sum,item)=>sum+item.tax,0);return{base,tax,total:base+tax}}
function resetPendingUpgradesIfNeeded(){if(pendingUpgrades.shipKey!==state.activeShip)pendingUpgrades={shipKey:state.activeShip,items:[]}}
function rebuildPendingUpgrades(items){const levels={...state.upgrades};pendingUpgrades.items=items.map(item=>{const levelFrom=levels[item.key]||0,base=upgradeCostAt(item.key,levelFrom),tax=Math.round(base*ECONOMY.upgradeTax);levels[item.key]=levelFrom+1;return{key:item.key,levelFrom,levelTo:levelFrom+1,base,tax}}).filter(item=>item.levelTo<=upgradeMax(item.key))}
buyUpgrade=key=>{resetPendingUpgradesIfNeeded();const queued=pendingUpgrades.items.filter(item=>item.key===key).length,levelFrom=(state.upgrades[key]||0)+queued,english=GAME_LANGUAGE==='en-US';if(levelFrom>=upgradeMax(key))return toast(english?'This upgrade is already at maximum level.':'Esta melhoria já está no nível máximo.');const base=upgradeCostAt(key,levelFrom),tax=Math.round(base*ECONOMY.upgradeTax),current=pendingUpgradeTotals();if(current.total+base+tax>state.credits)return toast(english?'Insufficient credits to add this upgrade.':'Créditos insuficientes para adicionar esta melhoria.');pendingUpgrades.items.push({key,levelFrom,levelTo:levelFrom+1,base,tax});renderGarage()};
