function currentGamepad(){return[...(navigator.getGamepads?.()||[])].find(Boolean)||null}
function visibleMenuElements(){const startVisible=!$('#startScreen').classList.contains('hidden'),root=startVisible?$('#startScreen'):document.querySelector('.view.active');if(!root)return[];return[...root.querySelectorAll('button:not([disabled]),select:not([disabled]),input:not([disabled])')].filter(element=>element.getClientRects().length&&!element.classList.contains('hidden'))}
