function activateGamepadFocus(){const elements=visibleMenuElements(),active=elements.includes(document.activeElement)?document.activeElement:elements[0];if(!active)return;active.focus();active.classList.add('gamepad-focus');if(active.tagName==='SELECT'){active.selectedIndex=(active.selectedIndex+1)%active.options.length;active.dispatchEvent(new Event('change',{bubbles:true}));return}active.click()}
function gamepadBack(){if(!$('#startScreen').classList.contains('hidden')){if(!$('#trainingDestinations').classList.contains('hidden'))showStartScreen(false);return}if(flight&&['ready','countdown','flying'].includes(flight.status))return;returnToMainMenu()}
function readGamepadButton(button){if(!button)return 0;const value=Number.isFinite(Number(button.value))?Number(button.value):0;if(value>.015)return Math.max(0,Math.min(1,value));return button.pressed?1:0}
