function processBindingCapture(pad){if(!bindingCapture)return false;const pressed=pad.buttons.map(button=>readGamepadButton(button)>.55);if(!bindingCapture.armed){if(!pressed.some(Boolean))bindingCapture.armed=true;return true}const index=pressed.findIndex(Boolean);if(index<0)return true;const action=bindingCapture.action,old=inputConfig.bindings[action],collision=Object.keys(inputConfig.bindings).find(key=>key!==action&&inputConfig.bindings[key]===index);if(collision)inputConfig.bindings[collision]=old;inputConfig.bindings[action]=index;bindingCapture=null;saveInputConfig();renderInputSettings();toast(GAME_LANGUAGE==='en-US'?'Motor button updated.':'Botão do motor atualizado.');return true}
