// Crédito empresarial: juros definidos pela economia do idioma e desconto de 50% nos juros na quitação antecipada.
function normalizeBusinessLoan(){const loan=state.afk?.loan;if(!loan)return null;const rate=ECONOMY.loanInterest,validPrincipal=Number.isFinite(loan.principalRemaining),validInterest=Number.isFinite(loan.interestRemaining);if(loan.termRate!==rate||!validPrincipal||!validInterest){loan.principalRemaining=Math.max(0,Math.round(validPrincipal?loan.principalRemaining:(loan.principal||0)));loan.interestRemaining=Math.max(0,Math.round(loan.principalRemaining*rate));loan.termRate=rate;loan.balance=loan.principalRemaining+loan.interestRemaining}return loan}
function reduceLoanComponents(nominalAmount){const loan=normalizeBusinessLoan();if(!loan)return{principal:0,interest:0,nominal:0};const nominal=Math.max(0,Math.min(Math.round(nominalAmount),loan.balance)),ratio=loan.balance?nominal/loan.balance:0;let principal=nominal===loan.balance?loan.principalRemaining:Math.min(loan.principalRemaining,Math.round(loan.principalRemaining*ratio)),interest=nominal-principal;if(interest>loan.interestRemaining){principal+=interest-loan.interestRemaining;interest=loan.interestRemaining}return{principal,interest,nominal:principal+interest}}
function applyAutomaticLoanPayment(amount){const loan=normalizeBusinessLoan();if(!loan)return 0;const parts=reduceLoanComponents(amount);loan.principalRemaining=Math.max(0,loan.principalRemaining-parts.principal);loan.interestRemaining=Math.max(0,loan.interestRemaining-parts.interest);loan.balance=loan.principalRemaining+loan.interestRemaining;if(loan.balance<=0)state.afk.loan=null;return parts.nominal}
